)

type limiterTransport struct{}

func (limiterTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	return &http.Response{StatusCode: 200, Body: io.NopCloser(strings.NewReader("ok")), Header: make(http.Header), Request: req}, nil
}

func TestSharedRateLimiterCanceledRequests(t *testing.T) {
	agent := &Agent{sources: []subscraping.Source{&blockingSource{}}}
	crl := newCustomRateLimit(map[string]uint{"mock": 1}, map[string]time.Duration{"mock": 200 * time.Millisecond})
	limiter := testRateLimiter(t, agent, 0, crl)
	if err := limiter.Wait(context.Background(), "mock"); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.WithValue(context.Background(), subscraping.CtxSourceArg, "mock"), 20*time.Millisecond)
	defer cancel()
	start := time.Now()
	var wg sync.WaitGroup
	for range 4 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			session := &subscraping.Session{RequestLimiter: limiter, Client: &http.Client{Transport: limiterTransport{}}}
			response, err := session.SimpleGet(ctx, "https://mock.invalid")
			if response != nil {
				session.DiscardHTTPResponse(response)
			}
			if err == nil {
				t.Error("canceled request succeeded")
			}
		}()
	}
	wg.Wait()
	if elapsed := time.Since(start); elapsed > 150*time.Millisecond {
		t.Fatalf("expired requests waited for provider refills: %s", elapsed)
	}
}

func TestSharedRateLimiterBurstAndCancellation(t *testing.T) {
	agent := &Agent{sources: []subscraping.Source{&blockingSource{}}}
	limiter := testRateLimiter(t, agent, 100, newCustomRateLimit(map[string]uint{"mock": 2}, map[string]time.Duration{"mock": 100 * time.Millisecond}))
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	var wg sync.WaitGroup
	successful := make(chan struct{}, 20)
	for range 20 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if limiter.Wait(ctx, "mock") == nil {
				successful <- struct{}{}
			}
		}()
	}
	wg.Wait()
	if len(successful) != 2 {
		t.Fatalf("initial burst=%d, want 2", len(successful))
	}
	// Expired waiters must not reserve tokens in the next window.
	next, cancelNext := context.WithTimeout(context.Background(), 150*time.Millisecond)
	defer cancelNext()
	for range 2 {
		if err := limiter.Wait(next, "mock"); err != nil {
			t.Fatal(err)
		}
	}
	canceled, stop := context.WithCancel(context.Background())
	stop()
	if err := limiter.Wait(canceled, "mock"); err != context.Canceled {
		t.Fatalf("canceled wait=%v", err)
	}
	if err := limiter.Wait(context.Background(), "missing"); err == nil {
		t.Fatal("missing source accepted")
	}
}

func TestSharedRateLimiterUnlimited(t *testing.T) {
	agent := &Agent{sources: []subscraping.Source{&blockingSource{}}}
	limiter := testRateLimiter(t, agent, 0, nil)
	for range 100 {
		if err := limiter.Wait(context.Background(), "mock"); err != nil {
			t.Fatal(err)
		}
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if err := limiter.Wait(ctx, "mock"); err != context.Canceled {
		t.Fatalf("unlimited canceled wait=%v", err)
	}
}

type requestingSource struct{ blockingSource }

func (s *requestingSource) Run(ctx context.Context, _ string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	session.Client.Transport = limiterTransport{}
	go func() {
		defer close(results)
		response, err := session.SimpleGet(ctx, "https://mock.invalid")
		if response != nil {
			session.DiscardHTTPResponse(response)
		}
		if err != nil {
			results <- subscraping.Result{Type: subscraping.Error, Error: err}
		}
	}()
	return results
}
func TestSharedRateLimiterEnumerationDeadline(t *testing.T) {
	agent := &Agent{sources: []subscraping.Source{&requestingSource{}}}
	limiter := testRateLimiter(t, agent, 0, newCustomRateLimit(map[string]uint{"mock": 1}, map[string]time.Duration{"mock": time.Second}))
	if err := limiter.Wait(context.Background(), "mock"); err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	var wg sync.WaitGroup
	for range 4 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range agent.EnumerateSubdomains("example.com", "", 0, 1, 20*time.Millisecond, WithRateLimiter(limiter)) {
			}
		}()
	}
	wg.Wait()
	if elapsed := time.Since(start); elapsed > 200*time.Millisecond {
		t.Fatalf("domain deadlines waited for refill: %s", elapsed)
	}
}

func testRateLimiter(t *testing.T, agent *Agent, global int, custom *subscraping.CustomRateLimit) *RateLimiter {
	t.Helper()
	limiter, err := agent.NewRateLimiter(context.Background(), global, custom)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = limiter.Close() })
	return limiter
}

package passive

import (
	"context"
	"fmt"
	"math"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/projectdiscovery/ratelimit"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

type EnumerationOptions struct {
	rateLimiter         subscraping.RequestLimiter
	customRateLimiter   *subscraping.CustomRateLimit
	maxResults          int
	maxResponseBodySize int64
}

type EnumerateOption func(opts *EnumerationOptions)

// WithRateLimiter borrows a request budget shared across enumerations.
// It overrides per-enumeration limits; sessions do not own its lifetime.
func WithRateLimiter(limiter subscraping.RequestLimiter) EnumerateOption {
	return func(opts *EnumerationOptions) {
		opts.rateLimiter = limiter
	}
}

func WithCustomRateLimit(crl *subscraping.CustomRateLimit) EnumerateOption {
	return func(opts *EnumerationOptions) {
		opts.customRateLimiter = crl
	}
}

// WithMaxResults sets a per-source limit on the number of results emitted.
// A value of 0 (the default) means no limit. Sources that paginate can honor
// this to avoid unnecessary requests (e.g. to stay within API quotas).
func WithMaxResults(maxResults int) EnumerateOption {
	return func(opts *EnumerationOptions) {
		opts.maxResults = maxResults
	}
}

// WithMaxResponseBodySize sets a cap on bytes read from passive-source HTTP
// response bodies. A value of 0 (the default) means no limit.
func WithMaxResponseBodySize(maxResponseBodySize int64) EnumerateOption {
	return func(opts *EnumerationOptions) {
		opts.maxResponseBodySize = maxResponseBodySize
	}
}

// EnumerateSubdomains wraps EnumerateSubdomainsWithCtx with an empty context
func (a *Agent) EnumerateSubdomains(domain string, proxy string, rateLimit int, timeout int, maxEnumTime time.Duration, options ...EnumerateOption) chan subscraping.Result {
	return a.EnumerateSubdomainsWithCtx(context.Background(), domain, proxy, rateLimit, timeout, maxEnumTime, options...)
}

// EnumerateSubdomainsWithCtx enumerates all the subdomains for a given domain
func (a *Agent) EnumerateSubdomainsWithCtx(ctx context.Context, domain string, proxy string, rateLimit int, timeout int, maxEnumTime time.Duration, options ...EnumerateOption) chan subscraping.Result {
	results := make(chan subscraping.Result)

	go func() {
		defer close(results)

		var enumerateOptions EnumerationOptions
		for _, enumerateOption := range options {
			enumerateOption(&enumerateOptions)
		}

		var multiRateLimiter *ratelimit.MultiLimiter
		var err error
		borrowedLegacy := false
		if limiter, ok := enumerateOptions.rateLimiter.(*RateLimiter); ok && limiter.legacy != nil {
			multiRateLimiter = limiter.legacy
			borrowedLegacy = true
		} else if enumerateOptions.rateLimiter == nil {
			multiRateLimiter, err = a.buildMultiRateLimiter(ctx, rateLimit, enumerateOptions.customRateLimiter)
		}
		if err != nil {
			results <- subscraping.Result{
				Type: subscraping.Error, Error: fmt.Errorf("could not init multi rate limiter for %s: %s", domain, err),
			}
			return
		}
		session, err := subscraping.NewSession(domain, proxy, multiRateLimiter, timeout)
		if err != nil {
			if !borrowedLegacy && multiRateLimiter != nil {
				multiRateLimiter.Stop()
			}
			results <- subscraping.Result{
				Type: subscraping.Error, Error: fmt.Errorf("could not init passive session for %s: %s", domain, err),
			}
			return
		}
		session.RequestLimiter = enumerateOptions.rateLimiter
		if borrowedLegacy {
			defer session.Client.CloseIdleConnections()
		} else {
			defer session.Close()
		}
		session.MaxResults = enumerateOptions.maxResults
		session.MaxResponseBodySize = enumerateOptions.maxResponseBodySize

		ctx, cancel := context.WithTimeout(ctx, maxEnumTime)

		wg := &sync.WaitGroup{}
		// Run each source in parallel on the target domain
		for _, runner := range a.sources {
			wg.Add(1)
			go func(source subscraping.Source) {
				defer wg.Done()
				ctxWithValue := context.WithValue(ctx, subscraping.CtxSourceArg, source.Name())
				sourceResults := source.Run(ctxWithValue, domain, session)
				for resp := range sourceResults {
					select {
					case <-ctx.Done():
						// stop forwarding but keep draining so the source goroutine
						// is never blocked on a send and can exit instead of leaking
						for range sourceResults {
						}
						return
					case results <- resp:
					}
				}
			}(runner)
		}
		wg.Wait()
		cancel()
	}()
	return results
}

func (a *Agent) buildMultiRateLimiter(ctx context.Context, globalRateLimit int, rateLimit *subscraping.CustomRateLimit) (*ratelimit.MultiLimiter, error) {
	var multiRateLimiter *ratelimit.MultiLimiter
	var err error
	if rateLimit == nil {
		rateLimit = &subscraping.CustomRateLimit{
			Custom: mapsutil.SyncLockMap[string, uint]{
				Map: make(map[string]uint),
			},
			CustomDuration: mapsutil.SyncLockMap[string, time.Duration]{
				Map: make(map[string]time.Duration),
			},
		}
	}
	for _, source := range a.sources {
		rl, duration := resolveSourceRateLimit(globalRateLimit, rateLimit, source.Name())

		if rl > 0 {
			multiRateLimiter, err = addRateLimiter(ctx, multiRateLimiter, source.Name(), rl, duration)
		} else {
			multiRateLimiter, err = addRateLimiter(ctx, multiRateLimiter, source.Name(), math.MaxUint32, time.Millisecond)
		}

		if err != nil {
			if multiRateLimiter != nil {
				multiRateLimiter.Stop()
			}
			return nil, err
		}
	}
	return multiRateLimiter, err
}

// resolveSourceRateLimit returns the effective rate limit and duration for a source.
// Priority: per-source custom limit > global -rl limit > unlimited.
// Duration comes from -rls (e.g. hackertarget=2/m → 2 per minute), defaulting to per-second.
func resolveSourceRateLimit(globalRateLimit int, rateLimit *subscraping.CustomRateLimit, sourceName string) (uint, time.Duration) {
	duration := time.Second // default: requests per second

	sourceLower := strings.ToLower(sourceName)
	if sourceRL, ok := rateLimit.Custom.Get(sourceLower); ok {
		rl := sourceRateLimitOrDefault(uint(max(globalRateLimit, 0)), sourceRL)
		// Use per-source duration from -rls if set (e.g. "2/m" → time.Minute)
		if d, ok := rateLimit.CustomDuration.Get(sourceLower); ok && d > 0 {
			duration = d
		}
		return rl, duration
	}

	// No per-source limit: fall back to global -rl
	if globalRateLimit > 0 {
		return uint(globalRateLimit), duration
	}

	return 0, duration
}

func sourceRateLimitOrDefault(defaultRateLimit uint, sourceRateLimit uint) uint {
	if sourceRateLimit > 0 {
		return sourceRateLimit
	}
	return defaultRateLimit
}

func addRateLimiter(ctx context.Context, multiRateLimiter *ratelimit.MultiLimiter, key string, maxCount uint, duration time.Duration) (*ratelimit.MultiLimiter, error) {
	if multiRateLimiter == nil {
		mrl, err := ratelimit.NewMultiLimiter(ctx, &ratelimit.Options{
			Key:         key,
			IsUnlimited: maxCount == math.MaxUint32,
			MaxCount:    maxCount,
			Duration:    duration,
		})
		return mrl, err
	}
	err := multiRateLimiter.Add(&ratelimit.Options{
		Key:         key,
		IsUnlimited: maxCount == math.MaxUint32,
		MaxCount:    maxCount,
		Duration:    duration,
	})
	return multiRateLimiter, err
}

func (a *Agent) GetStatistics() map[string]subscraping.Statistics {
	stats := make(map[string]subscraping.Statistics)
	sort.Slice(a.sources, func(i, j int) bool {
		return a.sources[i].Name() > a.sources[j].Name()
	})

	for _, source := range a.sources {
		stats[source.Name()] = source.Statistics()
	}
	return stats
}

package passive

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	mapsutil "github.com/projectdiscovery/utils/maps"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

func newCustomRateLimit(counts map[string]uint, durations map[string]time.Duration) *subscraping.CustomRateLimit {
	crl := &subscraping.CustomRateLimit{
		Custom: mapsutil.SyncLockMap[string, uint]{
			Map: make(map[string]uint),
		},
		CustomDuration: mapsutil.SyncLockMap[string, time.Duration]{
			Map: make(map[string]time.Duration),
		},
	}
	for k, v := range counts {
		_ = crl.Custom.Set(k, v)
	}
	for k, d := range durations {
		_ = crl.CustomDuration.Set(k, d)
	}
	return crl
}

func TestResolveSourceRateLimit_PerSourceOverride(t *testing.T) {
	// Per-source limit should override global
	crl := newCustomRateLimit(
		map[string]uint{"hackertarget": 5},
		map[string]time.Duration{"hackertarget": time.Minute},
	)

	rl, dur := resolveSourceRateLimit(10, crl, "hackertarget")
	assert.Equal(t, uint(5), rl)
	assert.Equal(t, time.Minute, dur)
}

func TestResolveSourceRateLimit_GlobalFallback(t *testing.T) {
	// Sources without per-source limit should use global -rl
	crl := newCustomRateLimit(nil, nil)

	rl, dur := resolveSourceRateLimit(10, crl, "crtsh")
	assert.Equal(t, uint(10), rl)
	assert.Equal(t, time.Second, dur)
}

func TestResolveSourceRateLimit_NoLimit(t *testing.T) {
	// No global and no per-source → unlimited (0)
	crl := newCustomRateLimit(nil, nil)

	rl, _ := resolveSourceRateLimit(0, crl, "crtsh")
	assert.Equal(t, uint(0), rl)
}

func TestResolveSourceRateLimit_ZeroValueRateLimit(t *testing.T) {
	// Zero-value CustomRateLimit (nil maps) should not panic and fall back to global
	rl, dur := resolveSourceRateLimit(5, &subscraping.CustomRateLimit{}, "crtsh")
	assert.Equal(t, uint(5), rl)
	assert.Equal(t, time.Second, dur)
}

func TestResolveSourceRateLimit_PerSourceDefaultDuration(t *testing.T) {
	// Per-source limit without explicit duration defaults to per-second
	crl := newCustomRateLimit(
		map[string]uint{"hackertarget": 3},
		nil,
	)

	rl, dur := resolveSourceRateLimit(0, crl, "hackertarget")
	assert.Equal(t, uint(3), rl)
	assert.Equal(t, time.Second, dur)
}

func TestBuildMultiRateLimiter_GlobalAppliedToAll(t *testing.T) {
	// With -rl 5 and no per-source overrides, all sources should be rate-limited
	agent := New([]string{"hackertarget", "crtsh"}, []string{}, false, false)
	crl := newCustomRateLimit(nil, nil)

	limiter, err := agent.buildMultiRateLimiter(context.Background(), 5, crl)
	require.NoError(t, err)
	require.NotNil(t, limiter)
}

func TestBuildMultiRateLimiter_NilRateLimit(t *testing.T) {
	// nil rateLimit should not panic (guard in buildMultiRateLimiter)
	agent := New([]string{"hackertarget"}, []string{}, false, false)

	limiter, err := agent.buildMultiRateLimiter(context.Background(), 0, nil)
	require.NoError(t, err)
	require.NotNil(t, limiter)
}

func TestBuildMultiRateLimiter_PerSourceWithDuration(t *testing.T) {
	// Per-source limit with custom duration (e.g. -rls hackertarget=2/m)
	agent := New([]string{"hackertarget", "crtsh"}, []string{}, false, false)
	crl := newCustomRateLimit(
		map[string]uint{"hackertarget": 2},
		map[string]time.Duration{"hackertarget": time.Minute},
	)

	limiter, err := agent.buildMultiRateLimiter(context.Background(), 0, crl)
	require.NoError(t, err)
	require.NotNil(t, limiter)
}

func TestBuildMultiRateLimiter_UnlimitedWhenNoLimits(t *testing.T) {
	// Without any rate limits, sources should get MaxUint32 (effectively unlimited)
	agent := New([]string{"hackertarget"}, []string{}, false, false)
	crl := newCustomRateLimit(nil, nil)

	limiter, err := agent.buildMultiRateLimiter(context.Background(), 0, crl)
	require.NoError(t, err)
	require.NotNil(t, limiter)
}

func TestResolveSourceRateLimit_PerSourceExceedsGlobal(t *testing.T) {
	// Per-source limit higher than global should be honoured
	// (the source was explicitly allowed more than the default)
	crl := newCustomRateLimit(
		map[string]uint{"hackertarget": 20},
		nil,
	)

	rl, dur := resolveSourceRateLimit(10, crl, "hackertarget")
	assert.Equal(t, uint(20), rl, "per-source limit should take precedence even when > global")
	assert.Equal(t, time.Second, dur)
}

func TestResolveSourceRateLimit_CaseInsensitive(t *testing.T) {
	// Source names should be case-insensitive for lookup
	crl := newCustomRateLimit(
		map[string]uint{"hackertarget": 5},
		nil,
	)

	// Try mixed case — should still match the lower-cased key
	rl, _ := resolveSourceRateLimit(0, crl, "HackerTarget")
	assert.Equal(t, uint(5), rl, "source name lookup should be case-insensitive")
}

