}

func TestCancellationReleasesBlockedResult(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	pool := New().NewResolutionPoolWithCtx(ctx, 1, false)
	pool.Tasks <- HostEntry{Host: "www.example.com"}
