type providerSource struct {
	delayedSource
	keys     []string
	observed []string
}

func (*providerSource) Name() string                               { return "testprovider" }
func (*providerSource) KeyRequirement() subscraping.KeyRequirement { return subscraping.RequiredKey }
func (*providerSource) NeedsKey() bool                             { return true }
func (s *providerSource) AddApiKeys(keys []string)                 { s.keys = slices.Clone(keys) }
func (s *providerSource) Run(_ context.Context, domain string, _ *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result, 1)
	defer close(results)
	s.observed = append(s.observed, s.keys...)
	results <- subscraping.Result{Source: s.Name(), Value: "www." + domain}
	return results
}

func TestRunnerProviderSnapshot(t *testing.T) {
	source := &providerSource{}
	old, exists := passive.NameSourceMap[source.Name()]
	passive.NameSourceMap[source.Name()] = source
	t.Cleanup(func() {
		if exists {
			passive.NameSourceMap[source.Name()] = old
		} else {
			delete(passive.NameSourceMap, source.Name())
		}
	})
	t.Setenv("TESTPROVIDER_API_KEY", "")
	file := filepath.Join(t.TempDir(), "providers.yaml")
	if err := os.WriteFile(file, []byte("testprovider:\n  - file-key\n"), 0600); err != nil {
		t.Fatal(err)
	}
	options := &Options{Sources: []string{source.Name()}, ProviderConfig: file, Threads: 4, Timeout: 1, MaxEnumerationTime: 1}
	first, err := NewRunner(options)
	if err != nil {
		t.Fatal(err)
	}
	options.Sources[0] = "chaos"
	if err := os.WriteFile(file, []byte("testprovider:\n  - changed-file-key\n"), 0600); err != nil {
		t.Fatal(err)
	}
	t.Setenv("TESTPROVIDER_API_KEY", "environment-key")
	second, err := NewRunner(&Options{Sources: []string{source.Name()}, ProviderConfig: file, Threads: 4, Timeout: 1, MaxEnumerationTime: 1})
	if err != nil {
		t.Fatal(err)
	}
	t.Setenv("TESTPROVIDER_API_KEY", "later-environment-key")
	for _, runner := range []*Runner{first, second, first} {
		if err := runner.EnumerateMultipleDomainsWithCtx(context.Background(), strings.NewReader("example.com\n"), nil); err != nil {
			t.Fatal(err)
		}
	}
	if !slices.Equal(source.observed, []string{"file-key", "environment-key", "file-key"}) {
		t.Fatalf("provider snapshots/precedence changed: %v", source.observed)
	}
}

// Package runner implements the mechanism to drive the
// subdomain enumeration process
package runner

package runner

import (
	"context"
	"errors"
	"io"
	"os"
	"path"
	"strings"
	"sync"
	"time"

	"github.com/hako/durafmt"

	"github.com/projectdiscovery/gologger"

	"github.com/projectdiscovery/subfinder/v2/pkg/passive"
	"github.com/projectdiscovery/subfinder/v2/pkg/resolve"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

const maxNumCount = 2

var replacer = strings.NewReplacer(
	"•.", "",
	"•", "",
	"*.", "",
)

// EnumerateSingleDomain wraps EnumerateSingleDomainWithCtx with an empty context
func (r *Runner) EnumerateSingleDomain(domain string, writers []io.Writer) (map[string]map[string]struct{}, error) {
	return r.EnumerateSingleDomainWithCtx(context.Background(), domain, writers)
}

// EnumerateSingleDomainWithCtx performs subdomain enumeration against a single domain
func (r *Runner) EnumerateSingleDomainWithCtx(ctx context.Context, domain string, writers []io.Writer) (map[string]map[string]struct{}, error) {
	gologger.Info().Msgf("Enumerating subdomains for %s\n", domain)

	// Check if the user has asked to remove wildcards explicitly.
	// If yes, create the resolution pool and get the wildcards for the current domain
	var resolutionPool *resolve.ResolutionPool
	if r.options.RemoveWildcard {
		resolutionPool = r.resolverClient.NewResolutionPoolWithCtx(ctx, max(1, r.options.Threads), r.options.RemoveWildcard)
		err := resolutionPool.InitWildcards(domain)
		if err != nil {
			// Log the error but don't quit.
			gologger.Warning().Msgf("Could not get wildcards for domain %s: %s\n", domain, err)
		}
	}

	// Run the passive subdomain enumeration
	now := time.Now()
	passiveResults := r.passiveAgent.EnumerateSubdomainsWithCtx(ctx, domain, r.options.Proxy, r.options.RateLimit, r.options.Timeout, time.Duration(r.options.MaxEnumerationTime)*time.Minute, passive.WithCustomRateLimit(r.rateLimit), passive.WithMaxResults(r.options.MaxResults), passive.WithMaxResponseBodySize(int64(r.options.MaxResponseBodySize)), passive.WithRateLimiter(r.sharedRateLimiter))

	wg := &sync.WaitGroup{}
	wg.Add(1)
	// Create a unique map for filtering duplicate subdomains out
	uniqueMap := make(map[string]resolve.HostEntry)
	// Create a map to track sources for each host
	sourceMap := make(map[string]map[string]struct{})
	// Plain hosts are written to the caller's writers as they are found. JSON,
	// -cs, -nW and -oI stay batched because their lines depend on later results.
	stream := !r.options.JSON && !r.options.CaptureSources && !r.options.RemoveWildcard && !r.options.HostIP
	var streamErr error
	skippedCounts := make(map[string]int)
	// Process the results in a separate goroutine
	go func() {
		for result := range passiveResults {
			if ctx.Err() != nil {
				continue
			}

			switch result.Type {
			case subscraping.Error:
				gologger.Warning().Msgf("Encountered an error with source %s: %s\n", result.Source, result.Error)
			case subscraping.Subdomain:
				value := normalizeSubdomain(result.Value)
				subdomain := sourceSubdomain(result.Value)
				// check if this subdomain is actually a wildcard subdomain
				// that may have further subdomains associated with it
				isWildcard := strings.Contains(value, "*."+subdomain)

				// Validate the subdomain found and remove wildcards from
				if !strings.HasSuffix(subdomain, "."+normalizeSubdomain(domain)) || !isValidSubdomain(subdomain) {
					skippedCounts[result.Source]++
					continue
				}

				if matchSubdomain := r.filterAndMatchSubdomain(subdomain); matchSubdomain {
					if _, ok := uniqueMap[subdomain]; !ok {
						sourceMap[subdomain] = make(map[string]struct{})
					}

					// Log the verbose message about the found subdomain per source
					if _, ok := sourceMap[subdomain][result.Source]; !ok {
						gologger.Verbose().Label(result.Source).Msg(subdomain)
					}

					sourceMap[subdomain][result.Source] = struct{}{}

					// Check if the subdomain is a duplicate. If not,
					// send the subdomain for resolution.
					if _, ok := uniqueMap[subdomain]; ok {
						skippedCounts[result.Source]++
						// even if it is duplicate if it was not marked as wildcard before but this source says it is wildcard
						// then we should mark it as wildcard
						if !uniqueMap[subdomain].WildcardCertificate && isWildcard {
							val := uniqueMap[subdomain]
							val.WildcardCertificate = true
							uniqueMap[subdomain] = val
						}
						continue
					}

					hostEntry := resolve.HostEntry{Domain: domain, Host: subdomain, Source: result.Source, WildcardCertificate: isWildcard}
					if r.options.ResultCallback != nil && !r.options.RemoveWildcard {
						r.options.ResultCallback(&hostEntry)
					}

					uniqueMap[subdomain] = hostEntry
					if stream && streamErr == nil {
						streamErr = r.writeHostLine(writers, hostEntry.Host)
					}
					// If the user asked to remove wildcard then send on the resolve
					// queue. Otherwise, if mode is not verbose print the results on
					// the screen as they are discovered.
					if r.options.RemoveWildcard {
						select {
						case resolutionPool.Tasks <- hostEntry:
						case <-ctx.Done():
						}
					}
				}
			}
		}
		// Close the task channel only if wildcards are asked to be removed
		if r.options.RemoveWildcard {
			close(resolutionPool.Tasks)
		}

		wg.Done()
	}()

	// If the user asked to remove wildcards, listen from the results
	// queue and write to the map. At the end, print the found results to the screen
	foundResults := make(map[string]resolve.Result)
	if r.options.RemoveWildcard {
		// Process the results coming from the resolutions pool
		for result := range resolutionPool.Results {
			switch result.Type {
			case resolve.Error:
				gologger.Warning().Msgf("Could not resolve host: %s\n", result.Error)
			case resolve.Subdomain:
				// Add the found subdomain to a map.
				if _, ok := foundResults[result.Host]; !ok {
					foundResults[result.Host] = result
					if r.options.ResultCallback != nil {
						r.options.ResultCallback(&resolve.HostEntry{Domain: domain, Host: result.Host, Source: result.Source, WildcardCertificate: result.WildcardCertificate})
					}
				}
			}
		}
	}

	wg.Wait()

	if r.options.RemoveWildcard {
		// Merge wildcard certificate information from uniqueMap into foundResults
		// This handles cases where a later source marked a subdomain as wildcard
		// after it was already sent to the resolution pool
		for host, result := range foundResults {
			if entry, ok := uniqueMap[host]; ok && entry.WildcardCertificate && !result.WildcardCertificate {
				result.WildcardCertificate = true
				foundResults[host] = result
			}
		}
	}

	if streamErr != nil {
		gologger.Error().Msgf("Could not write results for %s: %s\n", domain, streamErr)
		return nil, streamErr
	}

	if r.outputMu != nil {
		r.outputMu.Lock()
		defer r.outputMu.Unlock()
	}

	outputWriter := NewOutputWriter(r.options.JSON)

	var file *os.File

	if r.domainOutput {
		filename := r.options.OutputFile
		appendToFile := filename != ""
		if filename == "" && r.options.OutputDirectory != "" {
			filename = path.Join(r.options.OutputDirectory, domain)
			if r.options.JSON {
				filename += ".json"
			} else {
				filename += ".txt"
			}
		}

		if filename != "" {
			var err error

			file, err = outputWriter.createFile(filename, appendToFile)
			if err != nil {
				return nil, err
			}

			// Each domain owns its writer slice. File creation and all writes are
			// serialized, including repeated domains targeting the same output path.
			writers = append(append([]io.Writer(nil), writers...), file)
		}
	}

	// Now output all results in output writers
	var err error

	for _, writer := range writers {
		// A per-domain file is not shared with other workers, so it is written
		// once here; the other writers already received the streamed hosts.
		if stream && (file == nil || writer != io.Writer(file)) {
			continue
		}
		if r.options.HostIP {
			err = outputWriter.WriteHostIP(domain, foundResults, writer)
		} else {
			if r.options.RemoveWildcard {
				err = outputWriter.WriteHostNoWildcard(domain, foundResults, writer)
			} else {
				if r.options.CaptureSources {
					err = outputWriter.writeSourceHostEntries(domain, sourceMap, uniqueMap, writer)
				} else {
					err = outputWriter.WriteHost(domain, uniqueMap, writer)
				}
			}
		}

		if err != nil {
			gologger.Error().Msgf("Could not write results for %s: %s\n", domain, err)
			if file != nil {
				err = errors.Join(err, file.Close())
			}

			return nil, err
		}
	}

	if file != nil {
		if err := file.Close(); err != nil {
			return nil, err
		}
	}

	// Show found subdomain count in any case.
	duration := durafmt.Parse(time.Since(now)).LimitFirstN(maxNumCount).String()
	var numberOfSubDomains int
	if r.options.RemoveWildcard {
		numberOfSubDomains = len(foundResults)
	} else {
		numberOfSubDomains = len(uniqueMap)
	}

	gologger.Info().Msgf("Found %d subdomains for %s in %s\n", numberOfSubDomains, domain, duration)

	if r.options.Statistics {
		gologger.Info().Msgf("Printing source statistics for %s", domain)
		statistics := r.passiveAgent.GetStatistics()
		// This is a hack to remove the skipped count from the statistics
		// as we don't want to show it in the statistics.
		// TODO: Design a better way to do this.
		for source, count := range skippedCounts {
			if stat, ok := statistics[source]; ok {
				stat.Results -= count
				statistics[source] = stat
			}
		}

		printStatistics(statistics)
	}

	return sourceMap, nil
}

func (r *Runner) filterAndMatchSubdomain(subdomain string) bool {
	for _, filter := range r.filterRegexes {
		if filter.MatchString(subdomain) {
			return false
		}
	}

	if r.matchRegexes != nil {
		for _, match := range r.matchRegexes {
			if m := match.MatchString(subdomain); m {
				return true
			}
		}
		return false
	}

	return true
}

// writeHostLine writes one streamed host to every writer, holding the batch
// output lock so lines from concurrent domains do not interleave.
func (r *Runner) writeHostLine(writers []io.Writer, host string) error {
	if r.outputMu != nil {
		r.outputMu.Lock()
		defer r.outputMu.Unlock()
	}
	for _, writer := range writers {
		if _, err := io.WriteString(writer, host+"\n"); err != nil {
			return err
		}
	}
	return nil
}

