package runner

import (
	"net"
	"os"
	"slices"
	"strings"

	"github.com/projectdiscovery/dnsx/libs/dnsx"
	"github.com/projectdiscovery/subfinder/v2/pkg/passive"
	"github.com/projectdiscovery/subfinder/v2/pkg/resolve"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

// initializePassiveEngine creates the passive engine and loads sources etc
func (r *Runner) initializePassiveEngine(providerKeys map[string][]string) {
	// Snapshot credentials and selection once. Workers own fresh adapters, not
	// copies of the global sources or their mutable enumeration state.
	keys := make(map[string][]string, len(providerKeys))
	for name, values := range providerKeys {
		keys[name] = slices.Clone(values)
	}

	for _, source := range passive.NameSourceMap {
		requirement := source.KeyRequirement()
		if requirement == subscraping.RequiredKey || requirement == subscraping.OptionalKey {
			if value := os.Getenv(strings.ToUpper(source.Name()) + "_API_KEY"); value != "" {
				keys[strings.ToLower(source.Name())] = []string{value}
			}
		}
	}

	r.providerKeys = keys

	sources, excluded := slices.Clone(r.options.Sources), slices.Clone(r.options.ExcludeSources)
	all, recursive := r.options.All, r.options.OnlyRecursive
	r.newPassiveAgent = func() *passive.Agent {
		return passive.NewWithProviderConfig(sources, excluded, all, recursive, keys)
	}
	r.passiveAgent = r.newPassiveAgent()
}

// initializeResolver creates the resolver used to resolve the found subdomains
func (r *Runner) initializeResolver() error {
	var resolvers []string

	// If the file has been provided, read resolvers from the file
	if r.options.ResolverList != "" {
		var err error
		resolvers, err = loadFromFile(r.options.ResolverList)
		if err != nil {
			return err
		}
	}

	if len(r.options.Resolvers) > 0 {
		resolvers = append(resolvers, r.options.Resolvers...)
	} else {
		resolvers = append(resolvers, resolve.DefaultResolvers...)
	}

	// Add default 53 UDP port if missing
	for i, resolver := range resolvers {
		if !strings.Contains(resolver, ":") {
			resolvers[i] = net.JoinHostPort(resolver, "53")
		}
	}

	r.resolverClient = resolve.New()
	var err error
	r.resolverClient.DNSClient, err = dnsx.New(dnsx.Options{BaseResolvers: resolvers, MaxRetries: 5})
	if err != nil {
		return nil
	}

	return nil
}

package runner

import (
	"cmp"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"slices"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/passive"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

// keyProbeDomain is enumerated when no -d is given. It only needs to be a
// domain every source accepts; the key status comes from the responses.
const keyProbeDomain = "projectdiscovery.io"

// KeyStatus is the outcome of probing one provider key.
type KeyStatus string

const (
	KeyValid       KeyStatus = "valid"
	KeyInvalid     KeyStatus = "invalid"
	KeyRateLimited KeyStatus = "rate-limited"
	KeyError       KeyStatus = "error"
	// KeySkipped means the source did not use the key, usually a malformed one.
	KeySkipped KeyStatus = "skipped"
	// KeyUnverified means the probe got no error and no result, so the key
	// could not be confirmed. A timeout or a quota body lands here too.
	KeyUnverified KeyStatus = "unverified"
)

// KeyCheck is the result of probing one configured key of a source.
type KeyCheck struct {
	Source string    `json:"source"`
	Key    int       `json:"key"`
	Status KeyStatus `json:"status"`
	Error  string    `json:"error,omitempty"`
}

// CheckKeys probes every configured key of the selected sources, one key per
// request so a bad key cannot hide behind a good one, and writes a status per key.
func (r *Runner) CheckKeys(ctx context.Context, writer io.Writer) error {
	checks := r.checkKeys(ctx)
	if r.options.JSON {
		encoder := json.NewEncoder(writer)
		for _, check := range checks {
			if err := encoder.Encode(check); err != nil {
				return err
			}
		}
		return nil
	}
	if len(checks) == 0 {
		_, err := fmt.Fprintln(writer, "no provider keys configured")
		return err
	}
	for _, check := range checks {
		line := fmt.Sprintf("%s key %d: %s", check.Source, check.Key, check.Status)
		if check.Error != "" {
			line += " (" + check.Error + ")"
		}
		if _, err := fmt.Fprintln(writer, line); err != nil {
			return err
		}
	}
	return nil
}

func (r *Runner) checkKeys(ctx context.Context) []KeyCheck {
	domain := keyProbeDomain
	if len(r.options.Domain) > 0 {
		domain = r.options.Domain[0]
	}

	var (
		mu     sync.Mutex
		checks []KeyCheck
		wg     sync.WaitGroup
	)
	for _, name := range r.keyedSources() {
		keys := r.providerKeys[name]
		// One budget per source, shared by all of its keys, so the source's
		// rate limit holds across the probes.
		base := passive.NewWithProviderConfig([]string{name}, nil, false, false, map[string][]string{name: keys})
		limiter, err := base.NewRateLimiter(ctx, r.options.RateLimit, r.rateLimit)
		if err != nil {
			mu.Lock()
			checks = append(checks, KeyCheck{Source: name, Status: KeyError, Error: err.Error()})
			mu.Unlock()
			continue
		}
		wg.Add(1)
		// Keys of one source run in sequence to respect its rate limit.
		go func(name string, keys []string, limiter *passive.RateLimiter) {
			defer wg.Done()
			defer func() { _ = limiter.Close() }()
			for i, key := range keys {
				check := r.probeKey(ctx, name, key, domain, limiter)
				check.Key = i + 1
				mu.Lock()
				checks = append(checks, check)
				mu.Unlock()
			}
		}(name, keys, limiter)
	}
	wg.Wait()

	slices.SortFunc(checks, func(a, b KeyCheck) int {
		return cmp.Or(cmp.Compare(a.Source, b.Source), cmp.Compare(a.Key, b.Key))
	})
	return checks
}

// keyedSources returns the names of the sources with configured keys, narrowed
// by -s and -es. Custom sources registered in NameSourceMap are included.
func (r *Runner) keyedSources() []string {
	var names []string
	for name, source := range passive.NameSourceMap {
		if source.KeyRequirement() == subscraping.NoKey || len(r.providerKeys[name]) == 0 {
			continue
		}
		if len(r.options.Sources) > 0 && !slices.Contains(r.options.Sources, name) {
			continue
		}
		if slices.Contains(r.options.ExcludeSources, name) {
			continue
		}
		names = append(names, name)
	}
	return names
}

func (r *Runner) probeKey(ctx context.Context, name, key, domain string, limiter *passive.RateLimiter) KeyCheck {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	agent := passive.NewWithProviderConfig([]string{name}, nil, false, false, map[string][]string{name: {key}})
	results := agent.EnumerateSubdomainsWithCtx(ctx, domain, r.options.Proxy, r.options.RateLimit, r.options.Timeout,
		time.Duration(r.options.Timeout)*time.Second,
		passive.WithRateLimiter(limiter),
		passive.WithMaxResults(1),
		passive.WithMaxResponseBodySize(int64(r.options.MaxResponseBodySize)),
	)

	// A key is valid only when the source returned a result for it. No error
	// and no result (a quota body, a timeout) cannot confirm the key.
	check := KeyCheck{Source: name, Status: KeyUnverified}
	var firstErr error
	for result := range results {
		switch result.Type {
		case subscraping.Subdomain:
			// One result proves the key works; stop spending its quota.
			check.Status = KeyValid
			firstErr = nil
			cancel()
		case subscraping.Error:
			if check.Status != KeyValid && firstErr == nil && ctx.Err() == nil {
				firstErr = result.Error
			}
		}
	}
	switch {
	case check.Status == KeyValid:
	case firstErr != nil:
		check.Status, check.Error = classifyKeyError(firstErr, key)
	case agent.GetStatistics()[name].Skipped:
		check.Status = KeySkipped
	}
	return check
}

func classifyKeyError(err error, key string) (KeyStatus, string) {
	var statusErr *subscraping.StatusCodeError
	if errors.As(err, &statusErr) {
		message := fmt.Sprintf("status %d", statusErr.StatusCode)
		switch statusErr.StatusCode {
		case http.StatusUnauthorized, http.StatusForbidden:
			return KeyInvalid, message
		case http.StatusTooManyRequests:
			return KeyRateLimited, message
		}
		return KeyError, message
	}
	return KeyError, redactKey(err.Error(), key)
}

// minRedactLen keeps short fragments of a key from mangling unrelated text.
const minRedactLen = 6

// redactKey removes the key from an error message, since sources often put it
// in the request URL. Multi-part keys ("user:secret") are redacted per part.
// Each part is also redacted in its escaped and URL-encoded forms, because Go
// quotes a key with a newline or special characters before it reaches the error.
func redactKey(message, key string) string {
	for _, part := range append([]string{key}, strings.Split(key, ":")...) {
		if len(part) < minRedactLen {
			continue
		}
		forms := []string{part, url.QueryEscape(part), url.PathEscape(part)}
		if quoted := strconv.Quote(part); len(quoted) >= 2 {
			forms = append(forms, quoted[1:len(quoted)-1])
		}
		for _, form := range forms {
			message = strings.ReplaceAll(message, form, "[redacted]")
		}
	}
	return message
}

package runner

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/projectdiscovery/subfinder/v2/pkg/passive"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	"github.com/stretchr/testify/require"
)

// keyedSource sends its key in the query string, as many real sources do, and
// skips like they do when the key is malformed.
type keyedSource struct {
	url     string
	mu      sync.Mutex
	key     string
	skipped bool
}

func (s *keyedSource) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	go func() {
		defer close(results)
		s.mu.Lock()
		key := s.key
		s.skipped = key == "malformed"
		s.mu.Unlock()
		if key == "malformed" {
			return
		}
		resp, err := session.SimpleGet(ctx, s.url+"?apikey="+key)
		result := subscraping.Result{Type: subscraping.Subdomain, Source: s.Name(), Value: "www." + domain}
		if err != nil {
			result = subscraping.Result{Type: subscraping.Error, Source: s.Name(), Error: err}
		}
		session.DiscardHTTPResponse(resp)
		results <- result
	}()
	return results
}
func (*keyedSource) Name() string                               { return "test-keyed" }
func (*keyedSource) IsDefault() bool                            { return false }
func (*keyedSource) HasRecursiveSupport() bool                  { return false }
func (*keyedSource) NeedsKey() bool                             { return true }
func (*keyedSource) KeyRequirement() subscraping.KeyRequirement { return subscraping.RequiredKey }
func (s *keyedSource) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.key = keys[0]
}
func (s *keyedSource) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return subscraping.Statistics{Skipped: s.skipped}
}

func TestCheckKeys(t *testing.T) {
	statusByKey := map[string]int{"good": 200, "revoked": 401, "banned": 403, "exhausted": 429, "secret-broken": 500}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(statusByKey[r.URL.Query().Get("apikey")])
	}))
	defer server.Close()

	source := &keyedSource{url: server.URL}
	name := source.Name()
	passive.NameSourceMap[name] = source
	t.Cleanup(func() { delete(passive.NameSourceMap, name) })

	r := &Runner{
		options: &Options{Timeout: 5, JSON: true, Sources: []string{name}},
		providerKeys: map[string][]string{
			name: {"good", "revoked", "banned", "exhausted", "secret-broken", "malformed"},
		},
	}
	var out strings.Builder
	require.NoError(t, r.CheckKeys(context.Background(), &out))

	var got []KeyCheck
	for _, line := range strings.Split(strings.TrimSpace(out.String()), "\n") {
		var check KeyCheck
		require.NoError(t, json.Unmarshal([]byte(line), &check))
		got = append(got, check)
	}
	require.Equal(t, []KeyCheck{
		{Source: name, Key: 1, Status: KeyValid},
		{Source: name, Key: 2, Status: KeyInvalid, Error: "status 401"},
		{Source: name, Key: 3, Status: KeyInvalid, Error: "status 403"},
		{Source: name, Key: 4, Status: KeyRateLimited, Error: "status 429"},
		{Source: name, Key: 5, Status: KeyError, Error: "status 500"},
		{Source: name, Key: 6, Status: KeySkipped},
	}, got)
	require.NotContains(t, out.String(), "secret")
}

func TestRedactKey(t *testing.T) {
	message := `Get "https://api.example/?email=me@example.com&key=s3cr3t": dial tcp: timeout`
	require.Equal(t, `Get "https://api.example/?email=[redacted]&key=[redacted]": dial tcp: timeout`, redactKey(message, "me@example.com:s3cr3t"))
}

// silentSource accepts any key and returns nothing, like a quota body or a
// timeout does. Its key must not be reported as valid.
type silentSource struct{}

func (*silentSource) Run(_ context.Context, _ string, _ *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	close(results)
	return results
}
func (*silentSource) Name() string                               { return "test-silent" }
func (*silentSource) IsDefault() bool                            { return false }
func (*silentSource) HasRecursiveSupport() bool                  { return false }
func (*silentSource) NeedsKey() bool                             { return true }
func (*silentSource) KeyRequirement() subscraping.KeyRequirement { return subscraping.RequiredKey }
func (*silentSource) AddApiKeys([]string)                        {}
func (*silentSource) Statistics() subscraping.Statistics         { return subscraping.Statistics{} }

func TestCheckKeysNoResultIsUnverified(t *testing.T) {
	source := &silentSource{}
	name := source.Name()
	passive.NameSourceMap[name] = source
	t.Cleanup(func() { delete(passive.NameSourceMap, name) })

	r := &Runner{
		options:      &Options{Timeout: 5, JSON: true, Sources: []string{name}},
		providerKeys: map[string][]string{name: {"unconfirmed-key"}},
	}
	var out strings.Builder
	require.NoError(t, r.CheckKeys(context.Background(), &out))
	require.Contains(t, out.String(), `"status":"unverified"`)
	require.NotContains(t, out.String(), `"status":"valid"`)
}

func TestRedactKeyQuotedAndShortParts(t *testing.T) {
	// A key with a newline reaches the error quoted, as \n.
	require.Equal(t, `Get "https://api.example/?k=[redacted]": refused`,
		redactKey(`Get "https://api.example/?k=abc\ndef-secret": refused`, "abc\ndef-secret"))
	// A short part (under minRedactLen) must not mangle unrelated text.
	require.Equal(t, `reason: abx [redacted]`, redactKey("reason: abx verylongsecret", "ab:verylongsecret"))
}

// -check-keys with -o must write the report to the file, not only to stdout.
func TestCheckKeysWritesOutputFile(t *testing.T) {
	source := &silentSource{}
	name := source.Name()
	passive.NameSourceMap[name] = source
	t.Cleanup(func() { delete(passive.NameSourceMap, name) })

	file := filepath.Join(t.TempDir(), "keys.json")
	r := &Runner{
		options: &Options{Timeout: 5, JSON: true, CheckKeys: true, Sources: []string{name},
			OutputFile: file, Output: io.Discard},
		providerKeys: map[string][]string{name: {"unconfirmed-key"}},
	}
	require.NoError(t, r.RunEnumerationWithCtx(context.Background()))
	data, err := os.ReadFile(file)
	require.NoError(t, err)
	require.Contains(t, string(data), `"status":"unverified"`)
}

