		"foo..example.com",
		".example.com",
		"foo;bar.example.com",
		"foo:80.example.com",
		"foo@bar.example.com",
		strings.Repeat("a", 64) + ".example.com",
		strings.Repeat("a.", 130) + "com",
	}
	for _, host := range invalid {
