package subscraping

import (
	"bytes"
	"context"
	"crypto/tls"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/corpix/uarand"
	"github.com/projectdiscovery/ratelimit"

	"github.com/projectdiscovery/gologger"
)

// limitedResponseBody wraps a response body so that at most maxSize bytes can
// be read from it, while still closing the underlying body (so no
// connection/body leak). It is applied centrally so every source inherits the
// cap regardless of how it consumes the body (io.ReadAll, json.Decoder,
// bufio.Scanner, etc.).
type limitedResponseBody struct {
	io.Reader // io.LimitReader over the original body
	io.Closer // the original body's Close
}

// LimitResponseBody caps response.Body at maxSize bytes in place when maxSize
// is greater than zero. A maxSize of 0 or less leaves the body unchanged
// (unlimited; the default). It preserves the original body's Close.
// Exported so sources that (rarely) issue a raw client.Do — bypassing the
// session's httpRequestWrapper — can opt into the same protection.
func LimitResponseBody(response *http.Response, maxSize int64) {
	if response == nil || response.Body == nil || maxSize <= 0 {
		return
	}
	response.Body = &limitedResponseBody{
		Reader: io.LimitReader(response.Body, maxSize),
		Closer: response.Body,
	}
}

// NewSession creates a new session object for a domain
func NewSession(domain string, proxy string, multiRateLimiter *ratelimit.MultiLimiter, timeout int) (*Session, error) {
	Transport := &http.Transport{
		MaxIdleConns:        100,
		MaxIdleConnsPerHost: 100,
		IdleConnTimeout:     90 * time.Second,
		// Sources send API keys, so the server certificate must be verified.
		TLSClientConfig: &tls.Config{
			MinVersion: tls.VersionTLS12,
		},
		DialContext: (&net.Dialer{
			Timeout: time.Duration(timeout) * time.Second,
		}).DialContext,
	}

	// Add proxy
	if proxy != "" {
		proxyURL, _ := url.Parse(proxy)
		if proxyURL == nil {
			// Log warning but continue anyway
			gologger.Warning().Msgf("Invalid proxy provided: %s", proxy)
		} else {
			Transport.Proxy = http.ProxyURL(proxyURL)
		}
	}

	client := &http.Client{
		Transport: Transport,
		Timeout:   time.Duration(timeout) * time.Second,
	}

	session := &Session{Client: client, Timeout: timeout}

	// Initiate rate limit instance
	session.MultiRateLimiter = multiRateLimiter

	// Create a new extractor object for the current domain
	extractor, err := NewSubdomainExtractor(domain)
	session.Extractor = extractor

	return session, err
}

// Get makes a GET request to a URL with extended parameters
func (s *Session) Get(ctx context.Context, getURL, cookies string, headers map[string]string) (*http.Response, error) {
	return s.HTTPRequest(ctx, http.MethodGet, getURL, cookies, headers, nil, BasicAuth{})
}

// SimpleGet makes a simple GET request to a URL
func (s *Session) SimpleGet(ctx context.Context, getURL string) (*http.Response, error) {
	return s.HTTPRequest(ctx, http.MethodGet, getURL, "", map[string]string{}, nil, BasicAuth{})
}

// Post makes a POST request to a URL with extended parameters
func (s *Session) Post(ctx context.Context, postURL, cookies string, headers map[string]string, body io.Reader) (*http.Response, error) {
	return s.HTTPRequest(ctx, http.MethodPost, postURL, cookies, headers, body, BasicAuth{})
}

// SimplePost makes a simple POST request to a URL
func (s *Session) SimplePost(ctx context.Context, postURL, contentType string, body io.Reader) (*http.Response, error) {
	return s.HTTPRequest(ctx, http.MethodPost, postURL, "", map[string]string{"Content-Type": contentType}, body, BasicAuth{})
}

// HTTPRequest makes any HTTP request to a URL with extended parameters
func (s *Session) HTTPRequest(ctx context.Context, method, requestURL, cookies string, headers map[string]string, body io.Reader, basicAuth BasicAuth) (*http.Response, error) {
	req, err := http.NewRequestWithContext(ctx, method, requestURL, body)
	if err != nil {
		return nil, err
	}

	req.Header.Set("User-Agent", uarand.GetRandom())
	req.Header.Set("Accept", "*/*")
	req.Header.Set("Accept-Language", "en")

	if basicAuth.Username != "" || basicAuth.Password != "" {
		req.SetBasicAuth(basicAuth.Username, basicAuth.Password)
	}

	if cookies != "" {
		req.Header.Set("Cookie", cookies)
	}

	for key, value := range headers {
		req.Header.Set(key, value)
	}

	sourceName := ctx.Value(CtxSourceArg).(string)

	var mrlErr error
	if s.RequestLimiter != nil {
		mrlErr = s.RequestLimiter.Wait(ctx, sourceName)
	} else {
		mrlErr = s.MultiRateLimiter.Take(sourceName)
	}

	if mrlErr != nil {
		return nil, mrlErr
	}

	return httpRequestWrapper(s.Client, req, s.MaxResponseBodySize)
}

// DiscardHTTPResponse discards the response content by demand
func (s *Session) DiscardHTTPResponse(response *http.Response) {
	if response == nil {
		return
	}
	// Close regardless of how draining went. Returning early on a drain error
	// used to leak the connection in exactly the case this helper exists to
	// handle, and every source now reaches it through a defer.
	defer func() {
		if closeErr := response.Body.Close(); closeErr != nil {
			gologger.Warning().Msgf("Could not close response body: %s\n", closeErr)
		}
	}()
	if _, err := io.Copy(io.Discard, response.Body); err != nil {
		gologger.Warning().Msgf("Could not discard response body: %s\n", err)
	}
}

// Close the session
func (s *Session) Close() {
	if s.MultiRateLimiter != nil {
		s.MultiRateLimiter.Stop()
	}

	s.Client.CloseIdleConnections()
}

func httpRequestWrapper(client *http.Client, request *http.Request, maxResponseBodySize int64) (*http.Response, error) {
	response, err := client.Do(request)
	if err != nil {
		return nil, err
	}

	// Optionally cap the untrusted response body centrally so every source
	// (and the debug-logging path below) inherits the same bound when enabled.
	LimitResponseBody(response, maxResponseBodySize)

	if response.StatusCode != http.StatusOK {
		requestURL, _ := url.QueryUnescape(request.URL.String())

		gologger.Debug().MsgFunc(func() string {
			buffer := new(bytes.Buffer)
			_, _ = buffer.ReadFrom(response.Body)
			return fmt.Sprintf("Response for failed request against %s:\n%s", requestURL, buffer.String())
		})
		return response, &StatusCodeError{StatusCode: response.StatusCode, URL: requestURL}
	}
	return response, nil
}

// StatusCodeError is returned for a source response whose status is not 200 OK.
type StatusCodeError struct {
	StatusCode int
	URL        string
}

func (e *StatusCodeError) Error() string {
	return fmt.Sprintf("unexpected status code %d received from %s", e.StatusCode, e.URL)
}

package subscraping

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/ratelimit"
	"github.com/stretchr/testify/require"
)

func newConnectionTestSession(tb testing.TB) (*Session, context.Context) {
	tb.Helper()
	ctx := context.WithValue(tb.Context(), CtxSourceArg, "test")
	limiter, err := ratelimit.NewMultiLimiter(ctx, &ratelimit.Options{Key: "test", IsUnlimited: true})
	require.NoError(tb, err)
	session, err := NewSession("example.com", "", limiter, 5)
	if err != nil {
		limiter.Stop()
	}
	require.NoError(tb, err)
	tb.Cleanup(session.Close)
	return session, ctx
}

// trustTestServer makes the session trust the certificate of a TLS test server.
func trustTestServer(tb testing.TB, session *Session, server *httptest.Server) {
	tb.Helper()
	pool := x509.NewCertPool()
	pool.AddCert(server.Certificate())
	transport, ok := session.Client.Transport.(*http.Transport)
	require.True(tb, ok)
	transport.TLSClientConfig = &tls.Config{RootCAs: pool, MinVersion: tls.VersionTLS12}
}

// BenchmarkSessionConnectionReuse includes connection establishment in the first
// request and measures successive page requests through the same session.
func BenchmarkSessionConnectionReuse(b *testing.B) {
	for _, protocol := range []string{"HTTP", "HTTPS"} {
		b.Run(protocol, func(b *testing.B) {
			var connections atomic.Int64
			server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
				_, _ = io.WriteString(w, "a.example.com\n")
			}))
			server.Config.ConnState = func(_ net.Conn, state http.ConnState) {
				if state == http.StateNew {
					connections.Add(1)
				}
			}
			if protocol == "HTTPS" {
				server.StartTLS()
			} else {
				server.Start()
			}
			b.Cleanup(server.Close)
			session, ctx := newConnectionTestSession(b)
			if protocol == "HTTPS" {
				trustTestServer(b, session, server)
			}
			b.ReportAllocs()
			b.ResetTimer()
			for i := 0; i < b.N; i++ {
				response, err := session.SimpleGet(ctx, server.URL)
				if err != nil {
					b.Fatal(err)
				}
				session.DiscardHTTPResponse(response)
			}
			b.StopTimer()
			b.ReportMetric(float64(connections.Load())/float64(b.N), "connections/op")
		})
	}
}

func TestSessionConnectionReuse(t *testing.T) {
	for _, protocol := range []string{"HTTP", "HTTPS"} {
		for _, explicitClose := range []bool{false, true} {
			name := protocol + "/default"
			if explicitClose {
				name = protocol + "/explicit-close"
			}
			t.Run(name, func(t *testing.T) {
				var connections atomic.Int64
				server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
					_, _ = io.WriteString(w, "a.example.com\n")
				}))
				server.Config.ConnState = func(_ net.Conn, state http.ConnState) {
					if state == http.StateNew {
						connections.Add(1)
					}
				}
				if protocol == "HTTPS" {
					server.StartTLS()
				} else {
					server.Start()
				}
				t.Cleanup(server.Close)
				session, ctx := newConnectionTestSession(t)
				if protocol == "HTTPS" {
					trustTestServer(t, session, server)
				}
				var headers map[string]string
				if explicitClose {
					headers = map[string]string{"Connection": "close"}
				}
				const requests = 3
				for range requests {
					response, err := session.Get(ctx, server.URL, "", headers)
					require.NoError(t, err)
					body, err := io.ReadAll(response.Body)
					session.DiscardHTTPResponse(response)
					require.NoError(t, err)
					require.Equal(t, "a.example.com\n", string(body))
				}
				wantConnections := int64(1)
				if explicitClose {
					wantConnections = requests
				}
				require.Equal(t, wantConnections, connections.Load())
			})
		}
	}
}

func TestSessionIdleConnectionLifecycle(t *testing.T) {
	closed := make(chan struct{})
	server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "a.example.com\n")
	}))
	server.Config.ConnState = func(_ net.Conn, state http.ConnState) {
		if state == http.StateClosed {
			close(closed)
		}
	}
	server.Start()
	t.Cleanup(server.Close)
	session, ctx := newConnectionTestSession(t)
	transport := session.Client.Transport.(*http.Transport)
	require.Positive(t, transport.IdleConnTimeout, "unused pooled connections must expire")

	response, err := session.SimpleGet(ctx, server.URL)
	require.NoError(t, err)
	session.DiscardHTTPResponse(response)
	session.Close()
	select {
	case <-closed:
	case <-time.After(5 * time.Second):
		t.Fatal("session close did not release its idle connection")
	}
}

func TestSessionRejectsUntrustedCertificate(t *testing.T) {
	var received atomic.Bool
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		received.Store(true)
		_, _ = io.WriteString(w, "a.example.com\n")
	}))
	t.Cleanup(server.Close)
	session, ctx := newConnectionTestSession(t)

	response, err := session.Get(ctx, server.URL, "", map[string]string{"X-Api-Key": "test-key"})
	if response != nil {
		session.DiscardHTTPResponse(response)
	}
	require.Error(t, err)
	var unknownAuthority x509.UnknownAuthorityError
	require.ErrorAs(t, err, &unknownAuthority)
	require.False(t, received.Load(), "request must not reach a server with an untrusted certificate")
}

package subscraping

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

const testMaxResponseBodySize int64 = 64 * 1024 // 64KB — small enough for fast tests

// trackedBody records whether Close was called, so we can prove the size cap
// wrapper still closes the underlying body (no connection/body leak).
type trackedBody struct {
	io.Reader
	closed bool
}

func (t *trackedBody) Close() error {
	t.closed = true
	return nil
}

// TestLimitResponseBody_CapsOversizedBody verifies the central cap truncates a
// body larger than maxSize while still delegating Close to the original body.
func TestLimitResponseBody_CapsOversizedBody(t *testing.T) {
	orig := &trackedBody{Reader: newInfiniteReader()}
	resp := &http.Response{Body: orig}

	LimitResponseBody(resp, testMaxResponseBodySize)

	// Reading everything from the (now capped) body must stop at the limit
	// rather than streaming forever.
	n, err := io.Copy(io.Discard, resp.Body)
	require.NoError(t, err)
	assert.Equal(t, testMaxResponseBodySize, n, "body must be truncated to the cap")

	require.NoError(t, resp.Body.Close())
	assert.True(t, orig.closed, "Close must propagate to the original body (no leak)")
}

// TestLimitResponseBody_SmallBodyUntouched verifies that a legitimate small
// body is passed through unchanged when a cap is set.
func TestLimitResponseBody_SmallBodyUntouched(t *testing.T) {
	const payload = "sub1.example.com\nsub2.example.com\n"
	orig := &trackedBody{Reader: newStringReader(payload)}
	resp := &http.Response{Body: orig}

	LimitResponseBody(resp, testMaxResponseBodySize)

	data, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	assert.Equal(t, payload, string(data))

	require.NoError(t, resp.Body.Close())
	assert.True(t, orig.closed)
}

// TestLimitResponseBody_ZeroIsUnlimited verifies that maxSize <= 0 leaves the
// body uncapped (default product behavior).
func TestLimitResponseBody_ZeroIsUnlimited(t *testing.T) {
	const payload = "sub1.example.com\n"
	orig := &trackedBody{Reader: newStringReader(payload)}
	resp := &http.Response{Body: orig}

	LimitResponseBody(resp, 0)

	// Body must be the original closer (not wrapped).
	require.Equal(t, orig, resp.Body)

	data, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	assert.Equal(t, payload, string(data))
}

// TestLimitResponseBody_NilSafe verifies the helper tolerates a nil response or
// nil body without panicking.
func TestLimitResponseBody_NilSafe(t *testing.T) {
	assert.NotPanics(t, func() { LimitResponseBody(nil, testMaxResponseBodySize) })
	assert.NotPanics(t, func() { LimitResponseBody(&http.Response{}, testMaxResponseBodySize) })
}

// TestHTTPRequestWrapper_CapsResponseBody exercises the full session path
// (client.Do -> httpRequestWrapper) and proves the returned response body is
// bounded when a positive limit is configured.
func TestHTTPRequestWrapper_CapsResponseBody(t *testing.T) {
	const overflow = 4096
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		buf := make([]byte, 1024)
		remaining := int(testMaxResponseBodySize) + overflow
		for remaining > 0 {
			chunk := len(buf)
			if remaining < chunk {
				chunk = remaining
			}
			nw, werr := w.Write(buf[:chunk])
			if werr != nil {
				return
			}
			remaining -= nw
		}
	}))
	defer server.Close()

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, server.URL, nil)
	require.NoError(t, err)

	resp, err := httpRequestWrapper(server.Client(), req, testMaxResponseBodySize)
	require.NoError(t, err)
	defer func() { _ = resp.Body.Close() }()

	n, err := io.Copy(io.Discard, resp.Body)
	require.NoError(t, err)
	assert.Equal(t, testMaxResponseBodySize, n, "wrapper must cap the body when limit is set")
}

// TestHTTPRequestWrapper_UnlimitedByDefault verifies that a zero limit leaves
// the body readable beyond any artificial small cap.
func TestHTTPRequestWrapper_UnlimitedByDefault(t *testing.T) {
	const bodySize = 8 * 1024
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write(make([]byte, bodySize))
	}))
	defer server.Close()

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, server.URL, nil)
	require.NoError(t, err)

	resp, err := httpRequestWrapper(server.Client(), req, 0)
	require.NoError(t, err)
	defer func() { _ = resp.Body.Close() }()

	n, err := io.Copy(io.Discard, resp.Body)
	require.NoError(t, err)
	assert.Equal(t, int64(bodySize), n, "wrapper must not cap the body when limit is 0")
}

// --- small helpers (avoid pulling in strings/bytes just for the readers) ---

type infiniteReader struct{}

func (infiniteReader) Read(p []byte) (int, error) {
	for i := range p {
		p[i] = 'a'
	}
	return len(p), nil
}

func newInfiniteReader() io.Reader { return infiniteReader{} }

func newStringReader(s string) io.Reader { return &stringReader{data: s} }

type stringReader struct {
	data string
	pos  int
}

func (s *stringReader) Read(p []byte) (int, error) {
	if s.pos >= len(s.data) {
		return 0, io.EOF
	}
	n := copy(p, s.data[s.pos:])
	s.pos += n
	return n, nil
}

package subscraping

import (
	"errors"
	"net/http"
	"strings"
	"testing"
)

// failingBody reads a little, then errors, and records whether it was closed.
type failingBody struct {
	read   int
	closed bool
}

func (b *failingBody) Read(p []byte) (int, error) {
	b.read++
	if b.read > 1 {
		return 0, errors.New("mock read failure")
	}
	n := copy(p, "partial")
	return n, nil
}

func (b *failingBody) Close() error {
	b.closed = true
	return nil
}

// DiscardHTTPResponse has to close the body whether or not draining it works.
// Every source reaches it through a defer on the error path, so returning early
// on a drain error leaked the connection in exactly the case the helper is there
// to handle.
func TestDiscardHTTPResponseClosesOnDrainError(t *testing.T) {
	body := &failingBody{}
	session := &Session{}
	session.DiscardHTTPResponse(&http.Response{StatusCode: http.StatusTooManyRequests, Body: body})

	if !body.closed {
		t.Error("body was not closed after the drain failed: the connection cannot be reused")
	}
}

// The ordinary path still closes, and a nil response is still a no-op.
func TestDiscardHTTPResponseClosesOnSuccess(t *testing.T) {
	body := &trackingBody{Reader: strings.NewReader("ok")}
	session := &Session{}
	session.DiscardHTTPResponse(&http.Response{StatusCode: http.StatusOK, Body: body})

	if !body.closed {
		t.Error("body was not closed after a successful drain")
	}

	session.DiscardHTTPResponse(nil)
}

type trackingBody struct {
	*strings.Reader
	closed bool
}

func (b *trackingBody) Close() error {
	b.closed = true
	return nil
}

package subscraping

import (
	"regexp"
	"strings"
)

// RegexSubdomainExtractor is a concrete implementation of the SubdomainExtractor interface, using regex for extraction.
type RegexSubdomainExtractor struct {
	extractor *regexp.Regexp
}

// NewSubdomainExtractor creates a new regular expression to extract
// subdomains from text based on the given domain.
func NewSubdomainExtractor(domain string) (*RegexSubdomainExtractor, error) {
	// QuoteMeta escapes the domain so its dots (and any other metacharacters)
	// are matched literally. Without this, "example.com" also matches text like
	// "exampleXcom" because "." means "any character" in a regex.
	extractor, err := regexp.Compile(`(?i)[a-zA-Z0-9\*_.-]+\.` + regexp.QuoteMeta(domain))
	if err != nil {
		return nil, err
	}
	return &RegexSubdomainExtractor{extractor: extractor}, nil
}

// Extract implements the SubdomainExtractor interface, using the regex to find subdomains in the given text.
func (re *RegexSubdomainExtractor) Extract(text string) []string {
	indices := re.extractor.FindAllStringIndex(text, -1)
	matches := make([]string, 0, len(indices))
	for _, idx := range indices {
		// Skip matches that are only a prefix of a longer hostname, e.g.
		// "foo.example.com" found inside "foo.example.com.evil.org": these end at
		// the target domain but the host actually belongs to a different apex.
		if hostnameContinues(text, idx[1]) {
			continue
		}
		// Clone so the short subdomain doesn't keep the whole (potentially large)
		// text backing array alive: strings.ToLower returns the input unchanged
		// when it is already lowercase, which is the common case for hostnames.
		matches = append(matches, strings.Clone(strings.ToLower(text[idx[0]:idx[1]])))
	}
	return matches
}

// hostnameContinues reports whether the hostname at the given end index extends
// further in text, i.e. the match is not a complete host. A single trailing dot
// (the FQDN form "host.") is tolerated, but an additional label such as the
// ".evil.org" in "foo.example.com.evil.org" is treated as a continuation.
func hostnameContinues(text string, end int) bool {
	if end >= len(text) {
		return false
	}
	b := text[end]
	if isLabelByte(b) {
		return true
	}
	if b == '.' {
		return end+1 < len(text) && isLabelStart(text[end+1])
	}
	return false
}

func isLabelByte(b byte) bool {
	return isLabelStart(b) || b == '-' || b == '_'
}

func isLabelStart(b byte) bool {
	return b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b >= '0' && b <= '9'
}

package subscraping

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestRegexSubdomainExtractor_Extract(t *testing.T) {
	tests := []struct {
		name   string
		domain string
		text   string
		want   []string
	}{
		{
			name:   "simple subdomain",
			domain: "example.com",
			text:   "www.example.com",
			want:   []string{"www.example.com"},
		},
		{
			name:   "multi-level subdomain",
			domain: "example.com",
			text:   "a.b.c.example.com",
			want:   []string{"a.b.c.example.com"},
		},
		{
			name:   "case is normalized to lower",
			domain: "example.com",
			text:   "WWW.Example.COM",
			want:   []string{"www.example.com"},
		},
		{
			name:   "wildcard prefix is preserved",
			domain: "example.com",
			text:   "*.example.com",
			want:   []string{"*.example.com"},
		},
		{
			name:   "multiple subdomains in one blob",
			domain: "example.com",
			text:   "foo.example.com\nbar.example.com",
			want:   []string{"foo.example.com", "bar.example.com"},
		},
		{
			name:   "trailing dot (FQDN form) is kept",
			domain: "example.com",
			text:   "host.example.com.",
			want:   []string{"host.example.com"},
		},
		{
			// The dot in the domain must be literal: "example.com" must not match
			// "exampleXcom". Before escaping the domain, the regex "." matched any
			// character and produced this false positive.
			name:   "domain dots are literal, not wildcards",
			domain: "example.com",
			text:   "sub.exampleXcom",
			want:   nil,
		},
		{
			// A host that merely ends with the target domain but belongs to a
			// different apex must not be reported.
			name:   "domain as a prefix of another apex is rejected",
			domain: "example.com",
			text:   "foo.example.com.evil.org",
			want:   nil,
		},
		{
			name:   "longer label ending in domain is rejected",
			domain: "example.com",
			text:   "notexample.com",
			want:   nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			extractor, err := NewSubdomainExtractor(tt.domain)
			require.NoError(t, err)
			got := extractor.Extract(tt.text)
			assert.ElementsMatch(t, tt.want, got)
		})
	}
}

// Package archive contains parsing helpers shared by archive sources.
package archive

import "strings"

// DecodeLine decodes up to three layers of URL escapes without letting an
// unrelated malformed escape prevent valid escapes from being decoded. Any
// percent-prefixed hostname-shaped text left afterward is ambiguous: it may be
// an invalid escape or a fourth encoding layer. Exclude that span rather than
// interpreting escape digits as part of a hostname.
func DecodeLine(line string) string {
	for range 3 {
		decoded := decodeLayer(line)
		if decoded == line {
			break
		}
		line = decoded
	}
	if !strings.Contains(line, "%") {
		return line
	}
	b := []byte(line)
	for i := 0; i < len(b); i++ {
		if b[i] != '%' {
			continue
		}
		b[i] = ' '
		for i+1 < len(b) && hostnameByte(b[i+1]) {
			i++
			b[i] = ' '
		}
	}
	return string(b)
}

func decodeLayer(line string) string {
	if !strings.ContainsAny(line, "%+") {
		return line
	}
	b := make([]byte, 0, len(line))
	for i := 0; i < len(line); i++ {
		switch {
		case line[i] == '+':
			b = append(b, ' ')
		case line[i] == '%' && i+2 < len(line):
			high, low := unhex(line[i+1]), unhex(line[i+2])
			if high >= 0 && low >= 0 {
				b = append(b, byte(high<<4|low))
				i += 2
			} else {
				// A nonhex guard keeps this malformed percent from becoming a
				// valid escape when neighboring bytes decode in a later pass.
				// The final ambiguity filter removes the guard with its span.
				b = append(b, '%', '_')
			}
		case line[i] == '%':
			b = append(b, '%', '_')
		default:
			b = append(b, line[i])
		}
	}
	return string(b)
}

func unhex(b byte) int {
	switch {
	case b >= '0' && b <= '9':
		return int(b - '0')
	case b >= 'a' && b <= 'f':
		return int(b - 'a' + 10)
	case b >= 'A' && b <= 'F':
		return int(b - 'A' + 10)
	default:
		return -1
	}
}

// Keep in step with the source extractor's ASCII hostname character class.
func hostnameByte(b byte) bool {
	return b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b >= '0' && b <= '9' || b == '*' || b == '_' || b == '.' || b == '-'
}

package archive

import "testing"

func TestDecodeLine(t *testing.T) {
	cases := []struct{ input, want string }{
		{"https://2fa.example.com/", "https://2fa.example.com/"},
		{"%252F2fa.example.com/%25", "/2fa.example.com/   "},
		{"https://a.example.com/path%25", "https://a.example.com/path   "},
		{"%61.example.com", "a.example.com"},
		{"%2561.example.com", "a.example.com"},
		{"%252561.example.com", "a.example.com"},
		{"a+b%2Bc", "a b c"},
		{"%GGa.example.com/https://b.example.com", "                   /https://b.example.com"},
	}
	for _, tc := range cases {
		if got := DecodeLine(tc.input); got != tc.want {
			t.Errorf("DecodeLine(%q)=%q, want %q", tc.input, got, tc.want)
		}
	}
}

package subscraping

import (
	"math/rand"
	"net/http"
	"sync"
)

// KeyRing hands out the API keys of one source run. It starts at a random key
// to spread load, and moves to the next key when a response shows the current
// one was rejected (401, 403) or is out of quota (429).
type KeyRing[T any] struct {
	mu      sync.Mutex
	keys    []T
	current int
}

// NewKeyRing returns a ring over keys, starting at a random one. Empty
// entries are dropped: a configured blank key is not a key to send.
func NewKeyRing[T any](keys []T) *KeyRing[T] {
	kept := make([]T, 0, len(keys))
	for _, key := range keys {
		if s, isString := any(key).(string); isString && s == "" {
			continue
		}
		kept = append(kept, key)
	}
	ring := &KeyRing[T]{keys: kept}
	if len(kept) > 0 {
		ring.current = rand.Intn(len(kept))
	}
	return ring
}

// Empty reports whether the ring holds no keys.
func (r *KeyRing[T]) Empty() bool {
	return len(r.keys) == 0
}

// Key returns the current key, or the zero value when the ring is empty.
func (r *KeyRing[T]) Key() T {
	r.mu.Lock()
	defer r.mu.Unlock()
	var key T
	if len(r.keys) > 0 {
		key = r.keys[r.current]
	}
	return key
}

// Do sends request with the current key. While the response rejects the key,
// it discards that response and retries with the next one, trying each key at
// most once. The key that worked stays current, so later pages reuse it.
// An empty ring sends one request with the zero key, for sources whose key is
// optional.
func (r *KeyRing[T]) Do(session *Session, request func(key T) (*http.Response, error)) (*http.Response, error) {
	if r.Empty() {
		var zero T
		return request(zero)
	}
	r.mu.Lock()
	start := r.current
	r.mu.Unlock()
	// used is this call's own position in the ring. Other calls can move the
	// shared current key, but they cannot make this call repeat or skip a key.
	used := start
	for attempt := 1; ; attempt++ {
		resp, err := request(r.keys[used])
		if err == nil || resp == nil || !keyRejected(resp.StatusCode) || attempt == len(r.keys) {
			if used != start {
				// The key that worked stays current, so later pages reuse it.
				r.mu.Lock()
				r.current = used
				r.mu.Unlock()
			}
			return resp, err
		}
		session.DiscardHTTPResponse(resp)
		previous := used
		used = (used + 1) % len(r.keys)
		r.mu.Lock()
		// Advance the shared key only if nobody has moved it since this call
		// started, so concurrent rejections do not skip a key.
		if r.current == previous {
			r.current = used
		}
		r.mu.Unlock()
	}
}

func keyRejected(statusCode int) bool {
	switch statusCode {
	case http.StatusUnauthorized, http.StatusForbidden, http.StatusTooManyRequests:
		return true
	}
	return false
}

package subscraping

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"

	"github.com/projectdiscovery/ratelimit"
	"github.com/stretchr/testify/require"
)

func keyServer(t *testing.T, statusByKey map[string]int) (*Session, func(key string) (*http.Response, error), func() []string) {
	t.Helper()
	var mu sync.Mutex
	var seen []string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		key := r.URL.Query().Get("key")
		mu.Lock()
		seen = append(seen, key)
		mu.Unlock()
		w.WriteHeader(statusByKey[key])
	}))
	t.Cleanup(server.Close)
	ctx := context.WithValue(t.Context(), CtxSourceArg, "test")
	limiter, err := ratelimit.NewMultiLimiter(ctx, &ratelimit.Options{Key: "test", IsUnlimited: true})
	require.NoError(t, err)
	session, err := NewSession("example.com", "", limiter, 5)
	require.NoError(t, err)
	t.Cleanup(session.Close)
	request := func(key string) (*http.Response, error) {
		return session.SimpleGet(ctx, server.URL+"?key="+key)
	}
	return session, request, func() []string {
		mu.Lock()
		defer mu.Unlock()
		return append([]string(nil), seen...)
	}
}

func TestKeyRingMovesPastRejectedKeys(t *testing.T) {
	session, request, seen := keyServer(t, map[string]int{"revoked": 401, "banned": 403, "exhausted": 429, "good": 200})
	ring := NewKeyRing([]string{"revoked", "banned", "exhausted", "good"})

	resp, err := ring.Do(session, request)
	require.NoError(t, err)
	session.DiscardHTTPResponse(resp)
	require.Equal(t, "good", ring.Key())
	require.Equal(t, "good", seen()[len(seen())-1])
	require.LessOrEqual(t, len(seen()), 4)

	// The working key stays current for later pages.
	before := len(seen())
	resp, err = ring.Do(session, request)
	require.NoError(t, err)
	session.DiscardHTTPResponse(resp)
	require.Equal(t, []string{"good"}, seen()[before:])
}

func TestKeyRingTriesEachKeyOnce(t *testing.T) {
	session, request, seen := keyServer(t, map[string]int{"a": 401, "b": 429, "c": 403})
	ring := NewKeyRing([]string{"a", "b", "c"})

	resp, err := ring.Do(session, request)
	require.Error(t, err)
	require.True(t, keyRejected(resp.StatusCode), "the last rejection is returned, got %d", resp.StatusCode)
	session.DiscardHTTPResponse(resp)
	require.ElementsMatch(t, []string{"a", "b", "c"}, seen())
}

func TestKeyRingKeepsOtherErrors(t *testing.T) {
	session, request, seen := keyServer(t, map[string]int{"a": 500, "b": 200})
	ring := NewKeyRing([]string{"a", "b"})
	for ring.Key() != "a" {
		ring = NewKeyRing([]string{"a", "b"})
	}

	resp, err := ring.Do(session, request)
	require.Error(t, err)
	require.Equal(t, http.StatusInternalServerError, resp.StatusCode)
	session.DiscardHTTPResponse(resp)
	require.Equal(t, []string{"a"}, seen())
}

func TestKeyRingEmpty(t *testing.T) {
	ring := NewKeyRing[string](nil)
	require.True(t, ring.Empty())
	require.Equal(t, "", ring.Key())
	var sent []string
	_, err := ring.Do(nil, func(key string) (*http.Response, error) {
		sent = append(sent, key)
		return nil, nil
	})
	require.NoError(t, err)
	require.Equal(t, []string{""}, sent)
}

func TestKeyRingDropsBlankKeys(t *testing.T) {
	session, request, seen := keyServer(t, map[string]int{"revoked": 401, "good": 200})
	ring := NewKeyRing([]string{"", "revoked", "", "good"})

	resp, err := ring.Do(session, request)
	require.NoError(t, err)
	session.DiscardHTTPResponse(resp)
	require.NotContains(t, seen(), "")
	require.Equal(t, "good", seen()[len(seen())-1])
}

// Another call moves the shared key while this call is retrying. This call
// must still try each key once, in its own order, so it does not skip "b".
func TestKeyRingLocalSequenceSurvivesConcurrentMove(t *testing.T) {
	session, _, _ := keyServer(t, nil)
	ring := NewKeyRing([]string{"a", "b", "c"})
	ring.mu.Lock()
	ring.current = 0
	ring.mu.Unlock()

	var sent []string
	request := func(key string) (*http.Response, error) {
		sent = append(sent, key)
		switch key {
		case "a":
			// Simulate another call advancing the shared key to "c".
			ring.mu.Lock()
			ring.current = 2
			ring.mu.Unlock()
			return &http.Response{StatusCode: http.StatusUnauthorized, Body: http.NoBody}, errors.New("rejected")
		case "b":
			return &http.Response{StatusCode: http.StatusUnauthorized, Body: http.NoBody}, errors.New("rejected")
		}
		return &http.Response{StatusCode: http.StatusOK, Body: http.NoBody}, nil
	}
	resp, err := ring.Do(session, request)
	require.NoError(t, err)
	session.DiscardHTTPResponse(resp)
	require.Equal(t, []string{"a", "b", "c"}, sent)
}

// Package alienvault logic
package alienvault

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"slices"
	"sync"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

type alienvaultResponse struct {
	Detail     string `json:"detail"`
	Error      string `json:"error"`
	PassiveDNS []struct {
		Hostname string `json:"hostname"`
	} `json:"passive_dns"`
}

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		resp, err := keys.Do(session, func(key string) (*http.Response, error) {
			stats.Requests++
