		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		resp, err := keys.Do(session, func(key string) (*http.Response, error) {
			stats.Requests++
			return session.SimpleGet(ctx, fmt.Sprintf("https://api.c99.nl/subdomainfinder?key=%s&domain=%s&json", key, domain))
		})
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}

		defer func() {
			if err := resp.Body.Close(); err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
			}
		}()

		var response dnsdbLookupResponse
		err = jsoniter.NewDecoder(resp.Body).Decode(&response)
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			return
		}

		if response.Error != "" {
			results <- subscraping.Result{
				Source: s.Name(), Type: subscraping.Error, Error: fmt.Errorf("%v", response.Error),
			}
			stats.Errors++
			return
		}

		for _, data := range response.Subdomains {
			if !strings.HasPrefix(data.Subdomain, ".") {
				select {
				case <-ctx.Done():
					return
				case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: data.Subdomain}:
					stats.Results++
				}
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "c99"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

// Package censys logic
package censys

import (
	"bytes"
	"context"
	"net/http"
	"strings"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

const (
	// maxCensysPages is the maximum number of pages to fetch from the API
	maxCensysPages = 10
	// maxPerPage is the maximum number of results per page
	maxPerPage = 100
	// baseURL is the Censys Platform API base URL
	baseURL = "https://api.platform.censys.io"
	// searchEndpoint is the global data search query endpoint
	searchEndpoint = "/v3/global/search/query"
	// queryPrefix is the Censys query language prefix for certificate name search
	queryPrefix = "cert.names: "
	// authHeaderPrefix is the Bearer token prefix for Authorization header
	authHeaderPrefix = "Bearer "
	// contentTypeJSON is the Content-Type header value for JSON
	contentTypeJSON = "application/json"
	// orgIDHeader is the header name for organization ID
	orgIDHeader = "X-Organization-ID"
)

// apiKey holds the Personal Access Token and optional Organization ID
type apiKey struct {
	pat   string
	orgID string
}

// Platform API request body
type searchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields,omitempty"`
	PageSize int      `json:"page_size,omitempty"`
	Cursor   string   `json:"cursor,omitempty"`
}

// Platform API response structures
type response struct {
	Result result `json:"result"`
}

type result struct {
	Hits          []hit  `json:"hits"`
	TotalHits     int64  `json:"total_hits"`
	NextPageToken string `json:"next_page_token"`
}

type hit struct {
	CertificateV1 certificateV1 `json:"certificate_v1"`
}

type certificateV1 struct {
	Resource resource `json:"resource"`
}

type resource struct {
	Names []string `json:"names"`
}

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []apiKey
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Key().pat == "" {
			stats.Skipped = true
			return
		}

		// Honor an optional per-source result limit (0 = no limit) so a single
		// domain can't drain an API quota by paginating to the end.
		maxResults := session.MaxResults

		apiURL := baseURL + searchEndpoint
		cursor := ""
		currentPage := 1

		for {
			select {
			case <-ctx.Done():
				return
			default:
			}

			reqBody := searchRequest{
				Query:    queryPrefix + domain,
				Fields:   []string{"cert.names"},
				PageSize: maxPerPage,
			}
			if cursor != "" {
				reqBody.Cursor = cursor
			}

			bodyBytes, err := jsoniter.Marshal(reqBody)
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				return
			}

			resp, err := keys.Do(session, func(key apiKey) (*http.Response, error) {
				headers := map[string]string{
					"Content-Type":  contentTypeJSON,
					"Authorization": authHeaderPrefix + key.pat,
				}
				// Add Organization ID header if provided
				if key.orgID != "" {
					headers[orgIDHeader] = key.orgID
				}

				stats.Requests++
				return session.HTTPRequest(
					ctx,
					http.MethodPost,
					apiURL,
					"",
					headers,
					bytes.NewReader(bodyBytes),
					subscraping.BasicAuth{},
				)
			})

			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return
			}

			var censysResponse response
			err = jsoniter.NewDecoder(resp.Body).Decode(&censysResponse)
			_ = resp.Body.Close()
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				return
			}

			for _, hit := range censysResponse.Result.Hits {
				for _, name := range hit.CertificateV1.Resource.Names {
					select {
					case <-ctx.Done():
						return
					case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: name}:
						stats.Results++
					}
					if maxResults > 0 && stats.Results >= maxResults {
						return
					}
				}
			}

			cursor = censysResponse.Result.NextPageToken
			if cursor == "" || currentPage >= maxCensysPages {
				break
			}
			currentPage++
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "censys"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

// AddApiKeys parses and adds API keys.
// Format: "PAT:ORG_ID" where ORG_ID is required for paid accounts.
// Example: "censys_xxx_token:12345678-91011-1213"
func (s *Source) AddApiKeys(keys []string) {
	apiKeys := subscraping.CreateApiKeys(keys, func(pat, orgID string) apiKey {
		return apiKey{pat: pat, orgID: orgID}
	})
	// Also support single PAT without org ID for free users
	for _, key := range keys {
		if !strings.Contains(key, ":") && key != "" {
			apiKeys = append(apiKeys, apiKey{pat: key, orgID: ""})
		}
	}
	s.mu.Lock()
	s.apiKeys = apiKeys
	s.mu.Unlock()
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

package censys

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// rewriteTransport sends every request to the test server while preserving the
// original path/query, so the source's hardcoded api.platform.censys.io URL
// still reaches our handler.
type rewriteTransport struct {
	target *url.URL
}

func (r *rewriteTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	req.URL.Scheme = r.target.Scheme
	req.URL.Host = r.target.Host
	return http.DefaultTransport.RoundTrip(req)
}

func newTestSession(t *testing.T, server *httptest.Server, maxResults int) *subscraping.Session {
	t.Helper()
	target, err := url.Parse(server.URL)
	require.NoError(t, err)

	return &subscraping.Session{
		Client:           &http.Client{Transport: &rewriteTransport{target: target}, Timeout: 5 * time.Second},
		MultiRateLimiter: createTestMultiRateLimiter(context.Background()),
		MaxResults:       maxResults,
	}
}

func runCensys(t *testing.T, source *Source, session *subscraping.Session, domain string) (subs []string, errs []error) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	ctxWithValue := context.WithValue(ctx, subscraping.CtxSourceArg, "censys")

	for r := range source.Run(ctxWithValue, domain, session) {
		switch r.Type {
		case subscraping.Subdomain:
			subs = append(subs, r.Value)
		case subscraping.Error:
			errs = append(errs, r.Error)
		}
	}
	return
}

// With no per-source limit the source follows the page token until it is empty
// and returns every subdomain, so paid keys are never silently truncated.
func TestCensysSource_FollowsPagesWhenUnlimited(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		// Two pages of one name each, then the page token terminates.
		if n < 2 {
			_, _ = fmt.Fprintf(w, `{"result":{"hits":[{"certificate_v1":{"resource":{"names":["sub%d.example.com"]}}}],"next_page_token":"next-%d"}}`, n, n)
			return
		}
		_, _ = fmt.Fprintf(w, `{"result":{"hits":[{"certificate_v1":{"resource":{"names":["sub%d.example.com"]}}}],"next_page_token":""}}`, n)
	}))
	defer server.Close()

	source := &Source{}
	source.AddApiKeys([]string{"test_pat:test_org"})

	subs, errs := runCensys(t, source, newTestSession(t, server, 0), "example.com")

	assert.Empty(t, errs)
	assert.ElementsMatch(t, []string{"sub1.example.com", "sub2.example.com"}, subs)
	assert.Equal(t, 2, source.Statistics().Requests)
}

// When -max-results (session.MaxResults) is set, pagination must stop as soon
// as the limit is reached so a single domain can't drain an API quota.
func TestCensysSource_MaxResultsCapsPagination(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		// Always return one name plus a non-empty page token so the source would
		// keep paginating (up to maxCensysPages) without the max-results cap.
		_, _ = fmt.Fprintf(w, `{"result":{"hits":[{"certificate_v1":{"resource":{"names":["sub%d.example.com"]}}}],"next_page_token":"next-%d"}}`, n, n)
	}))
	defer server.Close()

	const limit = 3
	source := &Source{}
	source.AddApiKeys([]string{"test_pat:test_org"})

	subs, errs := runCensys(t, source, newTestSession(t, server, limit), "example.com")

	assert.Empty(t, errs, "no errors expected on the happy path")
	assert.Len(t, subs, limit, "should yield exactly max-results subdomains")
	assert.Equal(t, limit, source.Statistics().Requests, "request count must be capped by max-results")
	assert.Equal(t, int32(limit), atomic.LoadInt32(&hits))
}

package censys

import (
