}

func TestCertspotterSource_NoApiKey(t *testing.T) {
	source := &Source{}

	ctx := context.Background()
	mrl, _ := ratelimit.NewMultiLimiter(ctx, &ratelimit.Options{
		Key:         "certspotter",
		IsUnlimited: false,
		MaxCount:    math.MaxInt32,
		Duration:    time.Millisecond,
	})
	session := &subscraping.Session{Client: http.DefaultClient, MultiRateLimiter: mrl}
	ctxWithValue := context.WithValue(ctx, subscraping.CtxSourceArg, "certspotter")

	var count int
	for range source.Run(ctxWithValue, "example.com", session) {
		count++
	}
	assert.Equal(t, 0, count, "expected no results without an api key")
	assert.True(t, source.Statistics().Skipped)
}

// With no per-source limit the source walks the "after" cursor to the end and
// returns every subdomain, i.e. the default behaviour stays unbounded.
func TestCertspotterSource_FollowsCursorWhenUnlimited(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		// Two issuances, then an empty page terminates pagination.
		if n < 3 {
			_, _ = fmt.Fprintf(w, `[{"id":"%d","dns_names":["sub%d.example.com"]}]`, n, n)
			return
		}
		_, _ = fmt.Fprint(w, `[]`)
	}))
	defer server.Close()

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})

	subs, errs := runSource(t, source, newTestSession(t, server, 0), "example.com")

	assert.Empty(t, errs)
	assert.ElementsMatch(t, []string{"sub1.example.com", "sub2.example.com"}, subs)
}

// When -max-results (session.MaxResults) is set, pagination must stop as soon
// as the limit is reached so a single domain can't drain an API quota.
func TestCertspotterSource_MaxResultsCapsPagination(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		// Always return one issuance with a fresh id so the source would paginate
		// forever via the "after" cursor without the max-results cap.
		_, _ = fmt.Fprintf(w, `[{"id":"%d","dns_names":["sub%d.example.com"]}]`, n, n)
	}))
	defer server.Close()

	const limit = 3
	source := &Source{}
	source.AddApiKeys([]string{"test-key"})

	subs, errs := runSource(t, source, newTestSession(t, server, limit), "example.com")

	assert.Empty(t, errs, "no errors expected on the happy path")
	assert.Len(t, subs, limit, "should yield exactly max-results subdomains")
	assert.Equal(t, limit, source.Statistics().Requests, "request count must be capped by max-results")
	assert.Equal(t, int32(limit), atomic.LoadInt32(&hits))
}

// Package chaos logic
package chaos

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"slices"
	"sync"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

// baseURL is the Chaos API endpoint. It is a variable so tests can point the
// source at a local server.
var baseURL = "https://dns.projectdiscovery.io/dns"

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		// The request goes through the session like every other source, so it
		// honors -proxy, -timeout, the rate limits and -max-response-body-size.
		resp, err := keys.Do(session, func(key string) (*http.Response, error) {
			stats.Requests++
			return session.Get(ctx, fmt.Sprintf("%s/%s/subdomains", baseURL, domain), "", map[string]string{
				"Authorization": key,
				"Accept":        "application/json",
			})
		})
		// Registered before the error check: a non-200 reply comes back as a
		// response and an error together. DiscardHTTPResponse ignores nil.
		defer session.DiscardHTTPResponse(resp)
		if err != nil {
			s.sendError(ctx, results, err)
			stats.Errors++
			return
		}

		// The body is {"domain": "...", "subdomains": ["a", "b", ...], ...}.
		// Stream the list instead of decoding it whole: large domains can
		// return a very long one.
		decoder := json.NewDecoder(resp.Body)
		if err := seekSubdomains(decoder); err != nil {
			s.sendError(ctx, results, err)
			stats.Errors++
			return
		}
		for decoder.More() {
			var subdomain string
			if err := decoder.Decode(&subdomain); err != nil {
				s.sendError(ctx, results, err)
				stats.Errors++
				return
			}
			select {
			case <-ctx.Done():
				return
			case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: fmt.Sprintf("%s.%s", subdomain, domain)}:
				stats.Results++
			}
		}
		// More also reports false on a read error, so a truncated body only
		// shows up when the closing tokens are checked.
		if err := finishResponse(decoder); err != nil {
			s.sendError(ctx, results, err)
			stats.Errors++
		}
	}()

	return results
}

// sendError reports err unless the consumer has stopped reading and the
// context is done, so the goroutine can exit and close results.
func (s *Source) sendError(ctx context.Context, results chan<- subscraping.Result, err error) {
	select {
	case <-ctx.Done():
	case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}:
	}
}

// seekSubdomains advances the decoder to the first element of the
// "subdomains" array, skipping any other keys of the top-level object.
func seekSubdomains(decoder *json.Decoder) error {
	if err := expectDelim(decoder, '{'); err != nil {
		return err
	}
	for decoder.More() {
		token, err := decoder.Token()
		if err != nil {
			return err
		}
		if key, ok := token.(string); ok && key == "subdomains" {
			return expectDelim(decoder, '[')
		}
		var skip json.RawMessage
		if err := decoder.Decode(&skip); err != nil {
			return err
		}
	}
	return fmt.Errorf("no subdomains field in response")
}

// finishResponse consumes the end of the "subdomains" array and the rest of
// the top-level object.
func finishResponse(decoder *json.Decoder) error {
	if err := expectDelim(decoder, ']'); err != nil {
		return err
	}
	for decoder.More() {
		if _, err := decoder.Token(); err != nil {
			return err
		}
		var skip json.RawMessage
		if err := decoder.Decode(&skip); err != nil {
			return err
		}
	}
	return expectDelim(decoder, '}')
}

func expectDelim(decoder *json.Decoder, want json.Delim) error {
	token, err := decoder.Token()
	if err != nil {
		return err
	}
	if delim, ok := token.(json.Delim); !ok || delim != want {
		return fmt.Errorf("unexpected token %v in response, expected %v", token, want)
	}
	return nil
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "chaos"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

package chaos

import (
	"context"
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/ratelimit"
