	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func newLimiter(t *testing.T) *ratelimit.MultiLimiter {
	t.Helper()
	mrl, err := ratelimit.NewMultiLimiter(context.Background(), &ratelimit.Options{
		Key:         "chaos",
		IsUnlimited: false,
		MaxCount:    math.MaxInt32,
		Duration:    time.Millisecond,
	})
	require.NoError(t, err)
	return mrl
}

func setBaseURL(t *testing.T, u string) {
	t.Helper()
	old := baseURL
	baseURL = u
	t.Cleanup(func() { baseURL = old })
}

func runSource(t *testing.T, ctx context.Context, source *Source, session *subscraping.Session) (subs []string, errs []error) {
	t.Helper()
	ctx = context.WithValue(ctx, subscraping.CtxSourceArg, "chaos")
	for r := range source.Run(ctx, "example.com", session) {
		switch r.Type {
		case subscraping.Subdomain:
			subs = append(subs, r.Value)
		case subscraping.Error:
			errs = append(errs, r.Error)
		}
	}
	return subs, errs
}

func TestChaosSource_Results(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		assert.Equal(t, "/dns/example.com/subdomains", r.URL.Path)
		assert.Equal(t, "test-key", r.Header.Get("Authorization"))
		// Keys may come in any order; the list is found by name.
		_, _ = fmt.Fprint(w, `{"count":2,"meta":{"x":[1,2]},"domain":"example.com","subdomains":["www","api.dev"],"next":{"cursor":null}}`)
	}))
	defer server.Close()
	setBaseURL(t, server.URL+"/dns")

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})
	session := &subscraping.Session{Client: server.Client(), MultiRateLimiter: newLimiter(t)}

	subs, errs := runSource(t, context.Background(), source, session)
	assert.Empty(t, errs)
	assert.Equal(t, []string{"www.example.com", "api.dev.example.com"}, subs)
	stats := source.Statistics()
	assert.Equal(t, 1, stats.Requests)
	assert.Equal(t, 2, stats.Results)
	assert.Equal(t, 0, stats.Errors)
}

// The request must go through the session client, so -proxy applies to it.
func TestChaosSource_UsesSessionProxy(t *testing.T) {
	var proxied atomic.Int32
	proxy := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// A forward proxy receives the absolute URL of the target.
		if r.URL.Host == "chaos.invalid" && r.URL.Path == "/dns/example.com/subdomains" {
			proxied.Add(1)
		}
		_, _ = fmt.Fprint(w, `{"domain":"example.com","subdomains":["www"]}`)
	}))
	defer proxy.Close()
	setBaseURL(t, "http://chaos.invalid/dns")

	session, err := subscraping.NewSession("example.com", proxy.URL, newLimiter(t), 5)
	require.NoError(t, err)
	defer session.Close()

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})

	subs, errs := runSource(t, context.Background(), source, session)
	assert.Empty(t, errs)
	assert.Equal(t, []string{"www.example.com"}, subs)
	assert.Equal(t, int32(1), proxied.Load(), "request did not go through the session proxy")
}

func TestChaosSource_ErrorStatus(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, `{"error":"invalid key"}`, http.StatusUnauthorized)
	}))
	defer server.Close()
	setBaseURL(t, server.URL+"/dns")

	source := &Source{}
	source.AddApiKeys([]string{"bad-key"})
	session := &subscraping.Session{Client: server.Client(), MultiRateLimiter: newLimiter(t)}

	subs, errs := runSource(t, context.Background(), source, session)
	assert.Empty(t, subs)
	require.Len(t, errs, 1)
	assert.Contains(t, errs[0].Error(), "401")
	assert.Equal(t, 1, source.Statistics().Errors)
}

func TestChaosSource_MalformedBody(t *testing.T) {
	for name, body := range map[string]string{
		"not an object":           `["www"]`,
		"no subdomains":           `{"domain":"example.com"}`,
		"truncated list":          `{"subdomains":["www",`,
		"truncated after open":    `{"subdomains":[`,
		"truncated after element": `{"subdomains":["www"`,
		"truncated after list":    `{"subdomains":["www"]`,
		"truncated after key":     `{"subdomains":["www"],"count"`,
	} {
		t.Run(name, func(t *testing.T) {
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				_, _ = fmt.Fprint(w, body)
			}))
			defer server.Close()
			setBaseURL(t, server.URL+"/dns")

			source := &Source{}
			source.AddApiKeys([]string{"test-key"})
			session := &subscraping.Session{Client: server.Client(), MultiRateLimiter: newLimiter(t)}

			_, errs := runSource(t, context.Background(), source, session)
			assert.Len(t, errs, 1)
		})
	}
}

func TestChaosSource_NoApiKey(t *testing.T) {
	source := &Source{}
	session := &subscraping.Session{Client: http.DefaultClient, MultiRateLimiter: newLimiter(t)}

	subs, errs := runSource(t, context.Background(), source, session)
	assert.Empty(t, subs)
	assert.Empty(t, errs)
	assert.True(t, source.Statistics().Skipped)
	assert.Equal(t, 0, source.Statistics().Requests)
}

// Cancelling the context while results are streaming must close the channel
// instead of leaving a goroutine blocked on a send.
func TestChaosSource_StopsOnCancel(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		items := make([]string, 10000)
		for i := range items {
			items[i] = fmt.Sprintf(`"s%d"`, i)
		}
		_, _ = fmt.Fprintf(w, `{"subdomains":[%s]}`, strings.Join(items, ","))
	}))
	defer server.Close()
	setBaseURL(t, server.URL+"/dns")

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})
	session := &subscraping.Session{Client: server.Client(), MultiRateLimiter: newLimiter(t)}

	ctx, cancel := context.WithCancel(context.WithValue(context.Background(), subscraping.CtxSourceArg, "chaos"))
	results := source.Run(ctx, "example.com", session)
	<-results
	cancel()

	done := make(chan struct{})
	go func() {
		for range results {
		}
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("results channel was not closed after cancel")
	}
	assert.Less(t, source.Statistics().Results, 10000)
}

// A truncated body reports its error after a subdomain was sent. If the caller
// cancels and stops reading, the error send must not block the goroutine, so
// its deferred cleanup still runs and publishes the statistics.
func TestChaosSource_ErrorAfterCancelDoesNotBlock(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = fmt.Fprint(w, `{"subdomains":["www"]`)
	}))
	defer server.Close()
	setBaseURL(t, server.URL+"/dns")

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})
	session := &subscraping.Session{Client: server.Client(), MultiRateLimiter: newLimiter(t)}

	ctx, cancel := context.WithCancel(context.WithValue(context.Background(), subscraping.CtxSourceArg, "chaos"))
	defer cancel()
	results := source.Run(ctx, "example.com", session)
	<-results
	cancel()

	require.Eventually(t, func() bool {
		return source.Statistics().TimeTaken > 0
	}, 5*time.Second, 10*time.Millisecond, "goroutine blocked on the error send after cancel")
}

package chinaz

// chinaz  http://my.chinaz.com/ChinazAPI/DataCenter/MyDataApi
import (
	"context"
	"fmt"
	"io"
	"net/http"
	"slices"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		resp, err := keys.Do(session, func(key string) (*http.Response, error) {
			stats.Requests++
			return session.SimpleGet(ctx, fmt.Sprintf("https://apidatav2.chinaz.com/single/alexa?key=%s&domain=%s", key, domain))
		})
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}

		body, err := io.ReadAll(resp.Body)
		session.DiscardHTTPResponse(resp)
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			return
		}

		SubdomainList := jsoniter.Get(body, "Result").Get("ContributingSubdomainList")
		if SubdomainList.ValueType() != jsoniter.ArrayValue {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: fmt.Errorf("chinaz: unexpected response shape, missing Result.ContributingSubdomainList")}
			stats.Errors++
			return
		}

		_data := []byte(SubdomainList.ToString())
		for i := 0; i < SubdomainList.Size(); i++ {
			subdomain := jsoniter.Get(_data, i, "DataUrl").ToString()
			select {
			case <-ctx.Done():
				return
			case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: subdomain}:
				stats.Results++
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "chinaz"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

// Package commoncrawl logic
package commoncrawl

import (
	"bufio"
	"context"
	"fmt"
	"strconv"
	"strings"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping/internal/archive"
)

const (
	indexURL     = "https://index.commoncrawl.org/collinfo.json"
	maxYearsBack = 5
)

var year = time.Now().Year()

type indexResponse struct {
	ID     string `json:"id"`
	APIURL string `json:"cdx-api"`
}

// Source is the passive scraping agent
type Source struct {
	mu    sync.Mutex
	stats subscraping.Statistics
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		stats.Requests++
		resp, err := session.SimpleGet(ctx, indexURL)
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}

		var indexes []indexResponse
		err = jsoniter.NewDecoder(resp.Body).Decode(&indexes)
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}
		session.DiscardHTTPResponse(resp)

		years := make([]string, 0)
		for i := range maxYearsBack {
			years = append(years, strconv.Itoa(year-i))
		}

		searchIndexes := make(map[string]string)
		for _, year := range years {
			for _, index := range indexes {
				if strings.Contains(index.ID, year) {
					if _, ok := searchIndexes[year]; !ok {
						searchIndexes[year] = index.APIURL
						break
					}
				}
			}
		}

		for _, apiURL := range searchIndexes {
			further := s.getSubdomains(ctx, apiURL, domain, session, results, &stats)
			if !further {
				break
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "commoncrawl"
}

func (s *Source) IsDefault() bool {
	return false
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.NoKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(_ []string) {
	// no key needed
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

func (s *Source) getSubdomains(ctx context.Context, searchURL, domain string, session *subscraping.Session, results chan subscraping.Result, stats *subscraping.Statistics) bool {
	// Honor an optional per-source result limit (0 = no limit) so a single
	// domain can't trigger scanning every index to the end.
	maxResults := session.MaxResults
	for {
		select {
		case <-ctx.Done():
			return false
		default:
			var headers = map[string]string{"Host": "index.commoncrawl.org"}
			stats.Requests++
			resp, err := session.Get(ctx, fmt.Sprintf("%s?url=*.%s", searchURL, domain), "", headers)
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return false
			}

			scanner := bufio.NewScanner(resp.Body)
			for scanner.Scan() {
				select {
				case <-ctx.Done():
					session.DiscardHTTPResponse(resp)
					return false
				default:
				}
				line := scanner.Text()
				if line == "" {
					continue
				}
				line = archive.DecodeLine(line)
				for _, subdomain := range session.Extractor.Extract(line) {
					if subdomain != "" {
						subdomain = strings.ToLower(subdomain)

						select {
						case <-ctx.Done():
							session.DiscardHTTPResponse(resp)
							return false
						case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: subdomain}:
							stats.Results++
						}
						if maxResults > 0 && stats.Results >= maxResults {
							session.DiscardHTTPResponse(resp)
							return false
						}
					}
				}
			}
			session.DiscardHTTPResponse(resp)
			return true
		}
	}
}

