package sources_test

import (
	"context"
	"io"
	"net/http"
	"strings"
	"sync"
	"testing"
	"time"
)

// trackedBody reports whether the consumer closed it.
type trackedBody struct {
	io.Reader
	mu     sync.Mutex
	closed bool
}

func (b *trackedBody) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.closed = true
	return nil
}

func (b *trackedBody) isClosed() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.closed
}

// A source must close every response body it is handed, including on the error
// path. httpRequestWrapper returns the response *and* an error for any non-200
// status, so a source that returns on `err != nil` without draining leaks the
// connection for every rate-limited or unauthorized reply, which is the common
// case for a key-based source.
func TestSourcesCloseResponseBodyOnErrorStatus(t *testing.T) {
	// 429 is what an exhausted free-tier key returns; 403 is what a rejected one
	// returns, and some sources retry on it down a separate path.
	statuses := []int{http.StatusTooManyRequests, http.StatusForbidden}

	for _, source := range concurrencySources() {
		t.Run(source.Name(), func(t *testing.T) {
			for _, status := range statuses {
				t.Run(http.StatusText(status), func(t *testing.T) {
					ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
					defer cancel()

					var mu sync.Mutex
					var bodies []*trackedBody

					transport := transportFunc(func(req *http.Request) (*http.Response, error) {
						body := &trackedBody{Reader: strings.NewReader(`{"error":"denied"}`)}
						mu.Lock()
						bodies = append(bodies, body)
						mu.Unlock()
						return &http.Response{
							StatusCode: status,
							Status:     http.StatusText(status),
							Body:       body,
							Header:     http.Header{"Content-Type": []string{"application/json"}},
							Request:    req,
						}, nil
					})

					source.AddApiKeys(concurrencyKeys(source.Name()))
					mockChaosClient(t, source, transport)
					awaitRun(t, ctx, startRun(t, ctx, source, "example.com", transport, 0))

					mu.Lock()
					defer mu.Unlock()
					for i, body := range bodies {
						if !body.isClosed() {
							t.Errorf("response body %d was never closed: the connection cannot be reused", i)
						}
					}
				})
			}
		})
	}
}

// Package robtex logic
package robtex

import (
	"bufio"
	"bytes"
	"context"
	"fmt"
	"net/http"
	"slices"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

const (
	addrRecord     = "A"
	iPv6AddrRecord = "AAAA"
	baseURL        = "https://proapi.robtex.com/pdns"
)

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

type result struct {
	Rrname string `json:"rrname"`
	Rrdata string `json:"rrdata"`
	Rrtype string `json:"rrtype"`
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		headers := map[string]string{"Content-Type": "application/x-ndjson"}

		ips, err := enumerate(ctx, session, keys, fmt.Sprintf("%s/forward/%s", baseURL, domain), headers)
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			return
		}

		for _, result := range ips {
			select {
			case <-ctx.Done():
				return
			default:
			}
			if result.Rrtype == addrRecord || result.Rrtype == iPv6AddrRecord {
				domains, err := enumerate(ctx, session, keys, fmt.Sprintf("%s/reverse/%s", baseURL, result.Rrdata), headers)
				if err != nil {
					results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
					stats.Errors++
					return
				}
				for _, result := range domains {
					select {
					case <-ctx.Done():
						return
					case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: result.Rrdata}:
						stats.Results++
					}
				}
			}
		}
	}()

	return results
}

func enumerate(ctx context.Context, session *subscraping.Session, keys *subscraping.KeyRing[string], targetURL string, headers map[string]string) ([]result, error) {
	var results []result

	resp, err := keys.Do(session, func(key string) (*http.Response, error) {
		return session.Get(ctx, targetURL+"?key="+key, "", headers)
	})
	if err != nil {
		session.DiscardHTTPResponse(resp)
		return results, err
	}

	defer session.DiscardHTTPResponse(resp)

	scanner := bufio.NewScanner(resp.Body)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}
		var response result
		err = jsoniter.NewDecoder(bytes.NewBufferString(line)).Decode(&response)
		if err != nil {
			return results, err
		}

		results = append(results, response)
	}

	return results, nil
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "robtex"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

// Package scanmalware logic
package scanmalware

import (
	"context"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

// userAgent identifies subfinder to ScanMalware. The session sets a random browser
// User-Agent by default; headers passed to session.Get are applied afterwards and
// override it, which keeps this source's traffic attributable rather than looking
// like scraping.
const userAgent = "scanmalware-subfinder/1.0 (+https://github.com/projectdiscovery/subfinder)"

// subdomainLimit is the maximum the API accepts. It rejects larger values rather
// than clamping them.
const subdomainLimit = 5000

// smqlPageSize is the maximum the SMQL endpoint accepts, for the same reason.
const smqlPageSize = 100

// smqlMaxPages bounds the archive query so a very large domain cannot stall a run.
const smqlMaxPages = 20

type ctDNSResponse struct {
	Subdomains []string `json:"subdomains"`
	Truncated  bool     `json:"subdomains_truncated"`
}

// hostsResponse is the browser-observed host set. Hosts are grouped by the source
// that produced them and `truncated` is reported per source, so a capped list is never
// presented as a complete one.
type hostsResponse struct {
	Subdomains []string        `json:"subdomains"`
	Truncated  map[string]bool `json:"truncated"`
}

type smqlResponse struct {
	Results []struct {
		URL      string `json:"url"`
		FinalURL string `json:"final_url"`
	} `json:"results"`
}

// Source is the passive scraping agent
type Source struct {
	mu    sync.Mutex
	stats subscraping.Statistics
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)

	go func() {
		// A source can serve overlapping runs; each run owns its counters.
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		// The three queries are independent populations, so a failure in one must not
		// skip the others. Only a cancelled context stops the run.

		// Certificate Transparency DNS records. This is the enumeration source and
		// carries most of the answer.
		s.enumerateCTDNS(ctx, domain, session, results, &stats)
		if ctx.Err() != nil {
			return
		}

		// The public scan archive. Not redundant: a host that was scanned but never
		// held a certificate appears only here.
		s.enumerateArchive(ctx, domain, session, results, &stats)
		if ctx.Err() != nil {
			return
		}

		// Hosts a browser actually contacted while rendering pages on this domain.
		// A third population again: dev and staging hosts that hold no certificate
		// and were never scanned directly show up only here.
		s.enumerateObservedHosts(ctx, domain, session, results, &stats)
	}()

	return results
}

// enumerateCTDNS reads subdomains observed in Certificate Transparency DNS records.
func (s *Source) enumerateCTDNS(ctx context.Context, domain string, session *subscraping.Session, results chan subscraping.Result, stats *subscraping.Statistics) {
	requestURL := fmt.Sprintf("https://scanmalware.com/api/v1/ct/dns/%s?subdomain_limit=%d",
		url.PathEscape(domain), subdomainLimit)

	stats.Requests++
	resp, err := session.Get(ctx, requestURL, "", map[string]string{"User-Agent": userAgent})
	if err != nil {
		results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
		stats.Errors++
		session.DiscardHTTPResponse(resp)
		return
	}

	var body ctDNSResponse
	err = jsoniter.NewDecoder(resp.Body).Decode(&body)
	if err != nil {
		results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
		stats.Errors++
		s.closeBody(resp, results, stats)
		return
	}
	s.closeBody(resp, results, stats)

	// The API caps the list and says so. Report the cap rather than presenting a
	// truncated list as complete.
	if body.Truncated {
		results <- subscraping.Result{
			Source: s.Name(), Type: subscraping.Error,
			Error: fmt.Errorf("results truncated at %d subdomains, more exist", subdomainLimit),
		}
		stats.Errors++
	}

	s.emit(ctx, body.Subdomains, session, results, stats)
}

// enumerateArchive reads hosts present in the public scan archive.
func (s *Source) enumerateArchive(ctx context.Context, domain string, session *subscraping.Session, results chan subscraping.Result, stats *subscraping.Statistics) {
	for page := 1; page <= smqlMaxPages; page++ {
		query := url.Values{
			"q":     {"domain:*." + domain},
			"limit": {fmt.Sprint(smqlPageSize)},
			"page":  {fmt.Sprint(page)},
		}
		requestURL := "https://scanmalware.com/api/v1/search/smql?" + query.Encode()

		stats.Requests++
		resp, err := session.Get(ctx, requestURL, "", map[string]string{"User-Agent": userAgent})
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}

		var body smqlResponse
		err = jsoniter.NewDecoder(resp.Body).Decode(&body)
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			s.closeBody(resp, results, stats)
			return
		}
		s.closeBody(resp, results, stats)

		hosts := make([]string, 0, len(body.Results)*2)
		for _, row := range body.Results {
			hosts = append(hosts, hostOf(row.URL), hostOf(row.FinalURL))
		}
		if !s.emit(ctx, hosts, session, results, stats) {
			return
		}

		// A short page is the last page.
		if len(body.Results) < smqlPageSize {
			return
		}
	}

	// Falling out of the loop means the last allowed page was full, so there are more
	// archive results than were read. Report it rather than presenting a locally
	// truncated set as the complete one.
	results <- subscraping.Result{
		Source: s.Name(), Type: subscraping.Error,
		Error: fmt.Errorf("archive results truncated after %d pages, more exist", smqlMaxPages),
	}
	stats.Errors++
}

// enumerateObservedHosts reads the hosts a browser resolved and requested while
// rendering pages on the domain.
//
// The default source set is deliberate: it is limited to hosts actually contacted.
// The endpoint can also return hosts named in a CSP or extracted statically from
// script source, but only about a third of those were ever contacted, and subfinder
// has no way to carry that distinction to the user.
func (s *Source) enumerateObservedHosts(ctx context.Context, domain string, session *subscraping.Session, results chan subscraping.Result, stats *subscraping.Statistics) {
	requestURL := fmt.Sprintf("https://scanmalware.com/api/v1/hosts/%s?subdomains_only=true",
		url.PathEscape(domain))

	stats.Requests++
	resp, err := session.Get(ctx, requestURL, "", map[string]string{"User-Agent": userAgent})
	if err != nil {
		results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
		stats.Errors++
		session.DiscardHTTPResponse(resp)
		return
	}

	var body hostsResponse
	err = jsoniter.NewDecoder(resp.Body).Decode(&body)
	if err != nil {
		results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
		stats.Errors++
		s.closeBody(resp, results, stats)
		return
	}
	s.closeBody(resp, results, stats)

	for source, truncated := range body.Truncated {
		if truncated {
			results <- subscraping.Result{
				Source: s.Name(), Type: subscraping.Error,
				Error: fmt.Errorf("observed host results truncated for source %q, more exist", source),
			}
			stats.Errors++
		}
	}

	s.emit(ctx, body.Subdomains, session, results, stats)
}

// closeBody closes a response body and reports a close error the same way the rest
// of the sources do, rather than discarding it.
func (s *Source) closeBody(resp *http.Response, results chan subscraping.Result, stats *subscraping.Statistics) {
	if err := resp.Body.Close(); err != nil {
		results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
		stats.Errors++
	}
}

// hostOf returns the hostname of a URL, or an empty string.
func hostOf(rawURL string) string {
	if rawURL == "" {
		return ""
	}
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return ""
	}
	return parsed.Hostname()
}

// emit sends every extracted subdomain. It returns false when the context is done.
func (s *Source) emit(ctx context.Context, hosts []string, session *subscraping.Session, results chan subscraping.Result, stats *subscraping.Statistics) bool {
	for _, host := range hosts {
		// Wildcard certificates appear literally as "*.example.com" and are not
		// resolvable hosts.
		if host == "" || strings.HasPrefix(host, "*.") {
			continue
		}
		for _, value := range session.Extractor.Extract(host) {
			if value == "" {
				continue
			}
			select {
			case <-ctx.Done():
				return false
			case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: value}:
				stats.Results++
			}
		}
	}
	return true
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "scanmalware"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return true
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.NoKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(_ []string) {
	// no key needed
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

package scanmalware

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(req *http.Request) (*http.Response, error) {
	return f(req)
}

type unlimitedLimiter struct{}

func (unlimitedLimiter) Wait(ctx context.Context, _ string) error { return ctx.Err() }

func newTestSession(t testing.TB, domain string, transport http.RoundTripper) *subscraping.Session {
	t.Helper()
	extractor, err := subscraping.NewSubdomainExtractor(domain)
	if err != nil {
		t.Fatal(err)
	}
	return &subscraping.Session{
		Client:         &http.Client{Transport: transport},
		Extractor:      extractor,
		RequestLimiter: unlimitedLimiter{},
	}
}

func TestSourceConcurrentRuns(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	ctx = context.WithValue(ctx, subscraping.CtxSourceArg, "scanmalware")

	firstStarted := make(chan struct{})
	releaseFirst := make(chan struct{})
	transport := roundTripFunc(func(req *http.Request) (*http.Response, error) {
		if req.URL.Path == "/api/v1/ct/dns/first.example" {
			close(firstStarted)
			select {
			case <-releaseFirst:
			case <-req.Context().Done():
				return nil, req.Context().Err()
			}
		}
		body := `{}`
		switch req.URL.Path {
		case "/api/v1/ct/dns/first.example":
			body = `{"subdomains":["one.first.example"],"subdomains_truncated":true}`
		case "/api/v1/ct/dns/second.example":
			body = `{"subdomains":["one.second.example","two.second.example"]}`
		}
		return &http.Response{StatusCode: http.StatusOK, Body: io.NopCloser(strings.NewReader(body)), Header: make(http.Header)}, nil
	})

	source := &Source{}
	first := source.Run(ctx, "first.example", newTestSession(t, "first.example", transport))
	select {
	case <-firstStarted:
	case <-ctx.Done():
		t.Fatal("first run did not start its request")
	}
	if stats := source.Statistics(); stats != (subscraping.Statistics{}) {
		t.Errorf("unfinished first run published statistics: %+v", stats)
	}

	second := source.Run(ctx, "second.example", newTestSession(t, "second.example", transport))
	checkResults := func(results <-chan subscraping.Result, wantValues []string, wantErrors int) {
		t.Helper()
		var values []string
		var errorCount int
		for result := range results {
			if result.Source != source.Name() {
				t.Errorf("result source = %q, want %q", result.Source, source.Name())
			}
			switch result.Type {
			case subscraping.Subdomain:
				values = append(values, result.Value)
			case subscraping.Error:
				errorCount++
				if result.Error == nil || !strings.Contains(result.Error.Error(), "results truncated") {
					t.Errorf("unexpected source error: %v", result.Error)
				}
			}
		}
		if !slices.Equal(values, wantValues) || errorCount != wantErrors {
			t.Errorf("results/errors = %v/%d, want %v/%d", values, errorCount, wantValues, wantErrors)
		}
		stats := source.Statistics()
		if stats.Requests != 3 || stats.Results != len(wantValues) || stats.Errors != wantErrors {
			t.Errorf("statistics = %+v, want 3 requests, %d results, and %d errors", stats, len(wantValues), wantErrors)
		}
	}

	checkResults(second, []string{"one.second.example", "two.second.example"}, 0)
	close(releaseFirst)
	checkResults(first, []string{"one.first.example"}, 1)
}

func TestSourceConcurrentStartsAndStatistics(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	ctx = context.WithValue(ctx, subscraping.CtxSourceArg, "scanmalware")
	session := newTestSession(t, "example.com", roundTripFunc(func(*http.Request) (*http.Response, error) {
		return nil, fmt.Errorf("unexpected HTTP request")
	}))
	source := &Source{}
	const runs = 16
	start := make(chan struct{})
	done := make(chan struct{}, runs)
	for range runs {
		go func() {
			<-start
			for range source.Run(ctx, "example.com", session) {
				stats := source.Statistics()
				if stats != (subscraping.Statistics{}) && (stats.Requests != 1 || stats.Errors != 1 || stats.Results != 0) {
					t.Errorf("incomplete statistics snapshot: %+v", stats)
				}
			}
			done <- struct{}{}
		}()
	}
	close(start)
	for range runs {
		<-done
	}
	stats := source.Statistics()
	if stats.Requests != 1 || stats.Errors != 1 || stats.Results != 0 {
		t.Errorf("statistics = %+v, want one canceled request and no results", stats)
	}
}

type trackedBody struct {
	io.Reader
	closeErr error
	closed   *int
}

func (b *trackedBody) Close() error {
	*b.closed++
	return b.closeErr
}

func TestSourceRunStatistics(t *testing.T) {
	const body = `{"subdomains":["www.example.com","*.example.com","other.test"],"results":[{"url":"https://archive.example.com/a","final_url":"https://redirect.example.com/b"}]}`
	source := &Source{}
	// Reuse one source to also verify that each run starts with fresh counters.
	for _, tt := range []struct {
		name       string
		body       string
		status     int
		closeErr   error
		wantValues []string
		wantErrors int
	}{
		{
			name: "success", body: body, status: http.StatusOK,
			wantValues: []string{"www.example.com", "archive.example.com", "redirect.example.com", "www.example.com"},
		},
		{
			name: "truncated", status: http.StatusOK, wantErrors: 2,
			body:       `{"subdomains":["www.example.com"],"subdomains_truncated":true,"truncated":{"browser":true,"other":false}}`,
			wantValues: []string{"www.example.com", "www.example.com"},
		},
		{name: "http errors", body: `{}`, status: http.StatusServiceUnavailable, wantErrors: 3},
		{name: "decode errors", body: `{`, status: http.StatusOK, wantErrors: 3},
		{
			name: "close errors", body: body, status: http.StatusOK, closeErr: errors.New("close failed"), wantErrors: 3,
			wantValues: []string{"www.example.com", "archive.example.com", "redirect.example.com", "www.example.com"},
		},
		{name: "empty", body: `{}`, status: http.StatusOK},
	} {
		t.Run(tt.name, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			ctx = context.WithValue(ctx, subscraping.CtxSourceArg, "scanmalware")
			var requests, closed int
			session := newTestSession(t, "example.com", roundTripFunc(func(req *http.Request) (*http.Response, error) {
				requests++
				if req.Header.Get("User-Agent") != userAgent {
					t.Errorf("User-Agent = %q, want %q", req.Header.Get("User-Agent"), userAgent)
				}
				return &http.Response{
					StatusCode: tt.status,
					Body:       &trackedBody{Reader: strings.NewReader(tt.body), closeErr: tt.closeErr, closed: &closed},
					Header:     make(http.Header),
				}, nil
			}))
			var values []string
			var errorCount int
			for result := range source.Run(ctx, "example.com", session) {
				if result.Type == subscraping.Error {
					errorCount++
					if result.Error == nil {
						t.Error("error result has no error")
					}
				} else {
					values = append(values, result.Value)
				}
			}
			if !slices.Equal(values, tt.wantValues) || errorCount != tt.wantErrors {
				t.Errorf("results/errors = %v/%d, want %v/%d", values, errorCount, tt.wantValues, tt.wantErrors)
			}
			if requests != 3 || closed != requests {
				t.Errorf("requests/closed bodies = %d/%d, want 3/3", requests, closed)
			}
			stats := source.Statistics()
			if stats.Requests != requests || stats.Errors != errorCount || stats.Results != len(values) {
				t.Errorf("statistics do not match emitted results: %+v", stats)
			}
		})
	}
}

func BenchmarkSourceRun(b *testing.B) {
	ctx := context.WithValue(context.Background(), subscraping.CtxSourceArg, "scanmalware")
	session := newTestSession(b, "example.com", roundTripFunc(func(*http.Request) (*http.Response, error) {
		return &http.Response{
			StatusCode: http.StatusOK,
			Body:       io.NopCloser(strings.NewReader(`{"subdomains":["www.example.com"]}`)),
			Header:     make(http.Header),
		}, nil
	}))
	source := &Source{}
	b.ReportAllocs()
	for b.Loop() {
		for result := range source.Run(ctx, "example.com", session) {
			if result.Type == subscraping.Error {
				b.Fatal(result.Error)
			}
		}
		stats := source.Statistics()
		if stats.Requests != 3 || stats.Results != 2 || stats.Errors != 0 {
			b.Fatalf("unexpected statistics: %+v", stats)
		}
	}
}

// Package securitytrails logic
package securitytrails

import (
	"bytes"
	"context"
	"fmt"
	"net/http"
	"slices"
	"strings"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

type response struct {
	Meta struct {
		ScrollID string `json:"scroll_id"`
	} `json:"meta"`
	Records []struct {
		Hostname string `json:"hostname"`
	} `json:"records"`
	Subdomains []string `json:"subdomains"`
}

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		// Honor an optional per-source result limit (0 = no limit) so a single
		// domain can't drain an API quota by paginating to the end.
		maxResults := session.MaxResults

		var scrollId string
		// forbidden is set when any key in one request returned 403, even if a
		// later key's response is the one returned.
		var forbidden bool
		send := func(request func(headers map[string]string) (*http.Response, error)) (*http.Response, error) {
			return keys.Do(session, func(key string) (*http.Response, error) {
				stats.Requests++
				resp, err := request(map[string]string{"Content-Type": "application/json", "APIKEY": key})
				if resp != nil && resp.StatusCode == http.StatusForbidden {
					forbidden = true
				}
				return resp, err
			})
		}

		for {
			select {
			case <-ctx.Done():
				return
			default:
			}
			var resp *http.Response
			var err error
			forbidden = false

			if scrollId == "" {
				var requestBody = fmt.Appendf(nil, `{"query":"apex_domain='%s'"}`, domain)
				resp, err = send(func(headers map[string]string) (*http.Response, error) {
					return session.Post(ctx, "https://api.securitytrails.com/v1/domains/list?include_ips=false&scroll=true", "",
						headers, bytes.NewReader(requestBody))
				})
			} else {
				resp, err = send(func(headers map[string]string) (*http.Response, error) {
					return session.Get(ctx, fmt.Sprintf("https://api.securitytrails.com/v1/scroll/%s", scrollId), "", headers)
				})
			}

			if err != nil && forbidden {
				// The 403 body is about to be replaced, so drain it first.
				session.DiscardHTTPResponse(resp)
				resp, err = send(func(headers map[string]string) (*http.Response, error) {
					return session.Get(ctx, fmt.Sprintf("https://api.securitytrails.com/v1/domain/%s/subdomains", domain), "", headers)
				})
			}

			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return
			}

			var securityTrailsResponse response
			err = jsoniter.NewDecoder(resp.Body).Decode(&securityTrailsResponse)
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return
			}

			session.DiscardHTTPResponse(resp)

			for _, record := range securityTrailsResponse.Records {
				select {
				case <-ctx.Done():
					return
				case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: record.Hostname}:
					stats.Results++
				}
				if maxResults > 0 && stats.Results >= maxResults {
					return
				}
			}

			for _, subdomain := range securityTrailsResponse.Subdomains {
				select {
				case <-ctx.Done():
					return
				default:
				}
				if strings.HasSuffix(subdomain, ".") {
					subdomain += domain
				} else {
					subdomain = subdomain + "." + domain
				}
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: subdomain}
				stats.Results++
				if maxResults > 0 && stats.Results >= maxResults {
					return
				}
			}

			scrollId = securityTrailsResponse.Meta.ScrollID

			if scrollId == "" {
				break
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "securitytrails"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return true
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

