// Package subdomaincenter logic
package subdomaincenter

import (
	"context"
	"encoding/json"
	"net/http"
	"net/url"
	"slices"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

// pageSize is the number of names requested per authenticated page. The API
// accepts an explicit limit of up to 1,000,000, but smaller pages complete
// faster and are cheaper to retry individually.
const pageSize = 10000

// crawlKeySuffix opts an authenticated key into a live crawl, e.g.
// "subdomaincenter: [<key>:crawl]" in the provider config.
const crawlKeySuffix = "crawl"

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// page is one response from the cuttlefish engine.
type page struct {
	names         []string
	truncated     bool
	nextOffset    int
	authenticated bool
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)

		for offset := 0; ; {
			current, err := fetchPage(ctx, session, keys, domain, offset, &stats)
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				return
			}

			for _, name := range current.names {
				for _, subdomain := range session.Extractor.Extract(name) {
					select {
					case <-ctx.Done():
						return
					case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: subdomain}:
						stats.Results++
						if session.MaxResults > 0 && stats.Results >= session.MaxResults {
							return
						}
					}
				}
			}

			// The anonymous tier ignores limit/offset and always answers with a
			// single capped sample, so there is nothing to page through.
			if !current.authenticated || !current.truncated || len(current.names) == 0 {
				return
			}
			offset = current.nextOffset
		}
	}()

	return results
}

// fetchPage returns one page of the cuttlefish result set for the domain.
func fetchPage(ctx context.Context, session *subscraping.Session, keys *subscraping.KeyRing[string], domain string, offset int, stats *subscraping.Statistics) (*page, error) {
	var authenticated bool
	request := func(key string) (*http.Response, error) {
		apiKey, crawl := parseAPIKey(key)
		authenticated = apiKey != ""

		headers := map[string]string{"Accept": "application/json"}
		query := url.Values{}
		query.Set("domain", domain)
		query.Set("engine", "cuttlefish")
		if authenticated {
			// The key travels in a header only: the API rejects it as a query
			// parameter so it cannot leak through proxy, browser or CDN logs.
			headers["X-API-Key"] = apiKey
			query.Set("limit", strconv.Itoa(pageSize))
			query.Set("offset", strconv.Itoa(offset))
		}
		// A live crawl is billed against its own quota and is cooled down
		// per domain, so it is only worth asking for once, on the first page.
		if crawl && authenticated && offset == 0 {
			query.Set("crawl", "true")
		}
		stats.Requests++
		return session.Get(ctx, "https://api.subdomain.center/?"+query.Encode(), "", headers)
	}

	resp, err := keys.Do(session, request)
	if err != nil {
		session.DiscardHTTPResponse(resp)
		return nil, err
	}
	defer session.DiscardHTTPResponse(resp)

	var names []string
	if err := json.NewDecoder(resp.Body).Decode(&names); err != nil {
		return nil, err
	}

	current := &page{
		names:         names,
		truncated:     strings.EqualFold(resp.Header.Get("X-Truncated"), "true"),
		authenticated: authenticated,
		// Crawl-sourced names are added on top of the requested page, so the
		// response can hold more names than the page actually advanced by.
		nextOffset: offset + len(names),
	}
	if next, err := strconv.Atoi(resp.Header.Get("X-Next-Offset")); err == nil && next > offset {
		current.nextOffset = next
	}

	return current, nil
}

// parseAPIKey splits a configured key into the key itself and whether it opts
// into a live crawl.
func parseAPIKey(key string) (string, bool) {
	if apiKey, suffix, found := strings.Cut(key, ":"); found && strings.EqualFold(suffix, crawlKeySuffix) {
		return apiKey, true
	}
	return key, false
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "subdomaincenter"
}

func (s *Source) IsDefault() bool {
	return true
}

// HasRecursiveSupport indicates that we accept subdomains in addition to apex domains
func (s *Source) HasRecursiveSupport() bool {
	return true
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.OptionalKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

// Package thc logic
package thc

import (
	"bytes"
	"context"
	"encoding/json"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

type response struct {
	Domains []struct {
		Domain string `json:"domain"`
	} `json:"domains"`
	NextPageState string `json:"next_page_state"`
}

// Source is the passive scraping agent
type Source struct {
	mu    sync.Mutex
	stats subscraping.Statistics
}

type requestBody struct {
	Domain    string `json:"domain"`
	PageState string `json:"page_state"`
	Limit     int    `json:"limit"`
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		// Honor an optional per-source result limit (0 = no limit) so a single
		// domain can't drain an API quota by paginating to the end.
		maxResults := session.MaxResults

		var pageState string
		headers := map[string]string{"Content-Type": "application/json"}
		apiURL := "https://ip.thc.org/api/v1/lookup/subdomains"

		for {
			reqBody := requestBody{
				Domain:    domain,
				PageState: pageState,
				Limit:     1000,
			}

			bodyBytes, err := json.Marshal(reqBody)
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				return
			}

			stats.Requests++
			resp, err := session.Post(ctx, apiURL, "", headers, bytes.NewReader(bodyBytes))
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return
			}

			var thcResponse response
			err = jsoniter.NewDecoder(resp.Body).Decode(&thcResponse)
			session.DiscardHTTPResponse(resp)
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				return
			}

			for _, domainRecord := range thcResponse.Domains {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: domainRecord.Domain}
				stats.Results++
				if maxResults > 0 && stats.Results >= maxResults {
					return
				}
			}

			pageState = thcResponse.NextPageState

			if pageState == "" {
				break
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "thc"
}

func (s *Source) IsDefault() bool {
	return false
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.NoKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(_ []string) {
	// No API keys needed for THC
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

package thc

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"net/url"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/ratelimit"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// rewriteTransport sends every request to the test server's host while
// preserving the original path, so the source's hardcoded thc URL still
// resolves to our handler.
type rewriteTransport struct {
	target *url.URL
}

func (r *rewriteTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	req.URL.Scheme = r.target.Scheme
	req.URL.Host = r.target.Host
	return http.DefaultTransport.RoundTrip(req)
}

func runSource(t *testing.T, server *httptest.Server, maxResults int) (source *Source, subs []string, errs []error) {
	t.Helper()
	target, err := url.Parse(server.URL)
	require.NoError(t, err)

	mrl, err := ratelimit.NewMultiLimiter(context.Background(), &ratelimit.Options{
		Key:         "thc",
		IsUnlimited: false,
		MaxCount:    math.MaxInt32,
		Duration:    time.Millisecond,
	})
	require.NoError(t, err)
	session := &subscraping.Session{
		Client:           &http.Client{Transport: &rewriteTransport{target: target}, Timeout: 5 * time.Second},
		MultiRateLimiter: mrl,
		MaxResults:       maxResults,
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	ctx = context.WithValue(ctx, subscraping.CtxSourceArg, "thc")

	source = &Source{}
	for r := range source.Run(ctx, "example.com", session) {
		switch r.Type {
		case subscraping.Subdomain:
			subs = append(subs, r.Value)
		case subscraping.Error:
			errs = append(errs, r.Error)
		}
	}
	return source, subs, errs
}

// newPagedServer serves three pages of two names each, chained by page_state.
func newPagedServer(t *testing.T) (*httptest.Server, *int32) {
	t.Helper()
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req requestBody
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		page := int(atomic.AddInt32(&hits, 1))
		next := ""
		if page < 3 {
			next = fmt.Sprintf("state-%d", page)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = fmt.Fprintf(w, `{"domains":[{"domain":"a%d.example.com"},{"domain":"b%d.example.com"}],"next_page_state":%q}`, page, page, next)
	}))
	t.Cleanup(server.Close)
	return server, &hits
}

func TestTHCSource_FollowsPagesWhenUnlimited(t *testing.T) {
	server, hits := newPagedServer(t)

	source, subs, errs := runSource(t, server, 0)

	assert.Empty(t, errs)
	assert.Len(t, subs, 6)
	assert.Equal(t, 3, source.Statistics().Requests)
	assert.Equal(t, int32(3), atomic.LoadInt32(hits))
}

// With -max-results set, pagination must stop once the limit is reached
// instead of reading every page.
func TestTHCSource_HonorsMaxResults(t *testing.T) {
	server, hits := newPagedServer(t)

	source, subs, errs := runSource(t, server, 3)

	assert.Empty(t, errs)
	assert.Equal(t, []string{"a1.example.com", "b1.example.com", "a2.example.com"}, subs)
	assert.Equal(t, 2, source.Statistics().Requests)
	assert.Equal(t, int32(2), atomic.LoadInt32(hits))
}

