// Package urlscan logic
package urlscan

import (
	"context"
	"fmt"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

const (
	// baseURL is the URLScan API base URL
	baseURL = "https://urlscan.io/api/v1/search/"
	// maxPages is the maximum number of pages to fetch
	maxPages = 5
	// maxPerPage is the maximum results per page (URLScan max is 10000, but 100 is safer)
	maxPerPage = 100
)

// response represents the URLScan API response structure
type response struct {
	Results []struct {
		Task struct {
			Domain string `json:"domain"`
			URL    string `json:"url"`
		} `json:"task"`
		Page struct {
			Domain string `json:"domain"`
			URL    string `json:"url"`
		} `json:"page"`
		Sort []interface{} `json:"sort"`
	} `json:"results"`
	HasMore bool `json:"has_more"`
	Total   int  `json:"total"`
}

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		// Search with wildcard to get more subdomain results
		s.enumerate(ctx, domain, keys, session, results, &stats)
	}()

	return results
}

// enumerate performs the actual enumeration with pagination
func (s *Source) enumerate(ctx context.Context, domain string, keys *subscraping.KeyRing[string], session *subscraping.Session, results chan subscraping.Result, stats *subscraping.Statistics) {
	var searchAfter string
	currentPage := 0

	// Honor an optional per-source result limit (0 = no limit) so a single
	// domain can't drain an API quota by paginating to the end.
	maxResults := session.MaxResults

	for {
		select {
		case <-ctx.Done():
			return
		default:
		}

		if currentPage >= maxPages {
			break
		}

		// Build search URL
		searchURL := fmt.Sprintf("%s?q=domain:%s&size=%d", baseURL, url.QueryEscape(domain), maxPerPage)
		if searchAfter != "" {
			searchURL += "&search_after=" + url.QueryEscape(searchAfter)
		}

		resp, err := keys.Do(session, func(key string) (*http.Response, error) {
			stats.Requests++
			return session.Get(ctx, searchURL, "", map[string]string{"api-key": key})
		})
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}

		var data response
		err = jsoniter.NewDecoder(resp.Body).Decode(&data)
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}
		session.DiscardHTTPResponse(resp)

		// Process results - extract subdomains from multiple fields
		for _, result := range data.Results {
			candidates := []string{
				result.Task.Domain,
				result.Page.Domain,
			}

			// Also extract from URLs if present
			if result.Task.URL != "" {
				if u, err := url.Parse(result.Task.URL); err == nil {
					candidates = append(candidates, u.Hostname())
				}
			}
			if result.Page.URL != "" {
				if u, err := url.Parse(result.Page.URL); err == nil {
					candidates = append(candidates, u.Hostname())
				}
			}

			for _, candidate := range candidates {
				if candidate == "" {
					continue
				}
				for _, subdomain := range session.Extractor.Extract(candidate) {
					select {
					case <-ctx.Done():
						return
					case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: subdomain}:
						stats.Results++
					}
					if maxResults > 0 && stats.Results >= maxResults {
						return
					}
				}
			}
		}

		// Check pagination conditions
		if !data.HasMore || len(data.Results) == 0 {
			break
		}

		// Get sort value for next page
		lastResult := data.Results[len(data.Results)-1]
		if len(lastResult.Sort) == 0 {
			break
		}

		// Build search_after parameter
		sortValues := make([]string, len(lastResult.Sort))
		for i, v := range lastResult.Sort {
			switch val := v.(type) {
			case float64:
				sortValues[i] = fmt.Sprintf("%.0f", val)
			default:
				sortValues[i] = fmt.Sprintf("%v", v)
			}
		}
		searchAfter = strings.Join(sortValues, ",")
		currentPage++
	}
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "urlscan"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return true
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

// Package virustotal logic
package virustotal

import (
	"context"
	"fmt"
	"net/http"
	"slices"
	"sync"
	"time"

	jsoniter "github.com/json-iterator/go"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

type response struct {
	Data []Object `json:"data"`
	Meta Meta     `json:"meta"`
}

type Object struct {
	Id string `json:"id"`
}

type Meta struct {
	Cursor string `json:"cursor"`
}

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		// Honor an optional per-source result limit to avoid unnecessary
		// pagination requests (e.g. to stay within API quotas). 0 = no limit.
		maxResults := session.MaxResults

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}
		var cursor = ""
		for {
			select {
			case <-ctx.Done():
				return
			default:
			}
			var url = fmt.Sprintf("https://www.virustotal.com/api/v3/domains/%s/subdomains?limit=40", domain)
			if cursor != "" {
				url = fmt.Sprintf("%s&cursor=%s", url, cursor)
			}
			resp, err := keys.Do(session, func(key string) (*http.Response, error) {
				stats.Requests++
				return session.Get(ctx, url, "", map[string]string{"x-apikey": key})
			})
			if err != nil {
				// The free tier grants 500 requests/day; once it is exhausted every
				// call returns HTTP 429. Surface an actionable message instead of the
				// generic "unexpected status code 429" so operators know to supply an
				// enterprise key or lower the scope (see #1718).
				if resp != nil && resp.StatusCode == http.StatusTooManyRequests {
					// Wrap the status error so callers such as -check-keys can
					// still classify the 429 as rate-limited.
					err = fmt.Errorf("virustotal quota exhausted (HTTP 429); some subdomains for %s may be missing: %w", domain,
						&subscraping.StatusCodeError{StatusCode: http.StatusTooManyRequests, URL: url})
				}
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return
			}

			var data response
			err = jsoniter.NewDecoder(resp.Body).Decode(&data)
			// Close the body per iteration; deferring inside the loop would keep
			// every page's body (and its connection) open until the goroutine exits.
			if closeErr := resp.Body.Close(); closeErr != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: closeErr}
				stats.Errors++
			}
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				return
			}

			for _, subdomain := range data.Data {
				select {
				case <-ctx.Done():
					return
				case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: subdomain.Id}:
					stats.Results++
				}
				if maxResults > 0 && stats.Results >= maxResults {
					return
				}
			}
			cursor = data.Meta.Cursor
			if cursor == "" {
				break
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "virustotal"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return true
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

// AddApiKeys copies keys for subsequent runs.
func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

package virustotal

import (
	"context"
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"net/url"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/ratelimit"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// rewriteTransport sends every request to the test server's host while
// preserving the original path/query, so the source's hardcoded
// www.virustotal.com URL still resolves to our handler.
type rewriteTransport struct {
	target *url.URL
}

func (r *rewriteTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	req.URL.Scheme = r.target.Scheme
	req.URL.Host = r.target.Host
	return http.DefaultTransport.RoundTrip(req)
}

func newTestSession(t *testing.T, server *httptest.Server, maxResults int) *subscraping.Session {
	t.Helper()
	target, err := url.Parse(server.URL)
	require.NoError(t, err)

	mrl, err := ratelimit.NewMultiLimiter(context.Background(), &ratelimit.Options{
		Key:         "virustotal",
		IsUnlimited: false,
		MaxCount:    math.MaxInt32,
		Duration:    time.Millisecond,
	})
	require.NoError(t, err)

	return &subscraping.Session{
		Client:           &http.Client{Transport: &rewriteTransport{target: target}, Timeout: 5 * time.Second},
		MultiRateLimiter: mrl,
		MaxResults:       maxResults,
	}
}

func runSource(t *testing.T, source *Source, session *subscraping.Session, domain string) (subs []string, errs []error) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	ctxWithValue := context.WithValue(ctx, subscraping.CtxSourceArg, "virustotal")

	for r := range source.Run(ctxWithValue, domain, session) {
		switch r.Type {
		case subscraping.Subdomain:
			subs = append(subs, r.Value)
		case subscraping.Error:
			errs = append(errs, r.Error)
		}
	}
	return
}

func TestVirustotalSource_Metadata(t *testing.T) {
	source := &Source{}
	assert.Equal(t, "virustotal", source.Name())
	assert.True(t, source.IsDefault())
	assert.True(t, source.HasRecursiveSupport())
	assert.True(t, source.NeedsKey())
}

func TestVirustotalSource_NoApiKey(t *testing.T) {
	source := &Source{}

	ctx := context.Background()
	mrl, _ := ratelimit.NewMultiLimiter(ctx, &ratelimit.Options{
		Key:         "virustotal",
		IsUnlimited: false,
		MaxCount:    math.MaxInt32,
		Duration:    time.Millisecond,
	})
	session := &subscraping.Session{Client: http.DefaultClient, MultiRateLimiter: mrl}
	ctxWithValue := context.WithValue(ctx, subscraping.CtxSourceArg, "virustotal")

	var count int
	for range source.Run(ctxWithValue, "example.com", session) {
		count++
	}
	assert.Equal(t, 0, count, "expected no results without an api key")
	assert.Equal(t, 0, source.Statistics().Requests)
}

// With no per-source limit the source must follow the cursor to the end and
// return every subdomain, i.e. the default behaviour stays unbounded so paid
// keys are never silently truncated.
func TestVirustotalSource_FollowsCursorWhenUnlimited(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		// Three pages of one subdomain each, then the cursor terminates.
		if n < 3 {
			_, _ = fmt.Fprintf(w, `{"data":[{"id":"sub%d.example.com"}],"meta":{"cursor":"next-%d"}}`, n, n)
			return
		}
		_, _ = fmt.Fprintf(w, `{"data":[{"id":"sub%d.example.com"}],"meta":{"cursor":""}}`, n)
	}))
	defer server.Close()

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})

	subs, errs := runSource(t, source, newTestSession(t, server, 0), "example.com")

	assert.Empty(t, errs)
	assert.ElementsMatch(t, []string{"sub1.example.com", "sub2.example.com", "sub3.example.com"}, subs)
	assert.Equal(t, 3, source.Statistics().Requests)
}

// When -max-results (session.MaxResults) is set, pagination must stop as soon
// as the limit is reached so a single domain can't drain an API quota (#1718).
func TestVirustotalSource_MaxResultsCapsPagination(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		// Always return one subdomain plus a non-empty cursor so the source
		// would loop forever without the max-results cap.
		_, _ = fmt.Fprintf(w, `{"data":[{"id":"sub%d.example.com"}],"meta":{"cursor":"next-%d"}}`, n, n)
	}))
	defer server.Close()

	const limit = 3
	source := &Source{}
	source.AddApiKeys([]string{"test-key"})

	subs, errs := runSource(t, source, newTestSession(t, server, limit), "example.com")

	assert.Empty(t, errs, "no errors expected on the happy path")
	assert.Len(t, subs, limit, "should yield exactly max-results subdomains")
	assert.Equal(t, limit, source.Statistics().Requests, "request count must be capped by max-results")
	assert.Equal(t, int32(limit), atomic.LoadInt32(&hits))
}

// Cursor exhaustion must not waste an extra request.
func TestVirustotalSource_StopsWhenCursorEmpty(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		if n == 1 {
			_, _ = fmt.Fprint(w, `{"data":[{"id":"a.example.com"}],"meta":{"cursor":"more"}}`)
			return
		}
		_, _ = fmt.Fprint(w, `{"data":[{"id":"b.example.com"}],"meta":{"cursor":""}}`)
	}))
	defer server.Close()

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})

	subs, errs := runSource(t, source, newTestSession(t, server, 0), "example.com")

	assert.Empty(t, errs)
	assert.ElementsMatch(t, []string{"a.example.com", "b.example.com"}, subs)
	assert.Equal(t, 2, source.Statistics().Requests)
}

// On HTTP 429 (quota exhausted) the source must surface a human-readable error
// mentioning the quota, not a generic "unexpected status code 429" string.
func TestVirustotalSource_RateLimitedReturnsActionableError(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusTooManyRequests)
	}))
	defer server.Close()

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})

	_, errs := runSource(t, source, newTestSession(t, server, 0), "example.com")

	require.Len(t, errs, 1, "exactly one error expected on 429")
	assert.Contains(t, errs[0].Error(), "quota exhausted")
	assert.Contains(t, errs[0].Error(), "429")
	assert.Equal(t, 1, source.Statistics().Requests, "must not retry past the first 429")
	assert.Equal(t, 1, source.Statistics().Errors)
}

// Package waybackarchive logic
package waybackarchive

import (
	"bufio"
	"context"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping/internal/archive"
)

// Source is the passive scraping agent
type Source struct {
	mu    sync.Mutex
	stats subscraping.Statistics
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		stats.Requests++
		resp, err := session.SimpleGet(ctx, fmt.Sprintf("http://web.archive.org/cdx/search/cdx?url=*.%s/*&output=txt&fl=original&collapse=urlkey", domain))
		if err != nil {
			results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
			stats.Errors++
			session.DiscardHTTPResponse(resp)
			return
		}

		defer session.DiscardHTTPResponse(resp)

		scanner := bufio.NewScanner(resp.Body)
		for scanner.Scan() {
			select {
			case <-ctx.Done():
				return
			default:
			}
			line := scanner.Text()
			if line == "" {
				continue
			}
			line = archive.DecodeLine(line)
			for _, subdomain := range session.Extractor.Extract(line) {
				subdomain = strings.ToLower(subdomain)

				select {
				case <-ctx.Done():
					return
				case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: subdomain}:
					stats.Results++
				}
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "waybackarchive"
}

func (s *Source) IsDefault() bool {
	return false
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.NoKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(_ []string) {
	// no key needed
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

