	return "whoisxmlapi"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

// Package windvane logic
package windvane

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"slices"
	"strconv"
	"sync"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

type response struct {
	Code int          `json:"code"`
	Msg  string       `json:"msg"`
	Data responseData `json:"data"`
}

type responseData struct {
	List         []domainEntry `json:"list"`
	PageResponse pageInfo      `json:"page_response"`
}

type domainEntry struct {
	Domain string `json:"domain"`
}

type pageInfo struct {
	Total     string `json:"total"`
	Count     string `json:"count"`
	TotalPage string `json:"total_page"`
}

type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		keys := subscraping.NewKeyRing(apiKeys)
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		// Honor an optional per-source result limit (0 = no limit) so a single
		// domain can't drain an API quota by paginating to the end.
		maxResults := session.MaxResults

		page := 1
		count := 1000
		for {
			select {
			case <-ctx.Done():
				return
			default:
			}
			var resp *http.Response
			var err error

			requestBody, _ := json.Marshal(map[string]interface{}{"domain": domain, "page_request": map[string]int{"page": page, "count": count}})
			resp, err = keys.Do(session, func(key string) (*http.Response, error) {
				stats.Requests++
				return session.Post(ctx, "https://windvane.lichoin.com/trpc.backendhub.public.WindvaneService/ListSubDomain",
					"", map[string]string{"Content-Type": "application/json", "X-Api-Key": key}, bytes.NewReader(requestBody))
			})

			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return
			}

			var windvaneResponse response
			err = json.NewDecoder(resp.Body).Decode(&windvaneResponse)
			if err != nil {
				results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}
				stats.Errors++
				session.DiscardHTTPResponse(resp)
				return
			}

			for _, record := range windvaneResponse.Data.List {
				select {
				case <-ctx.Done():
					session.DiscardHTTPResponse(resp)
					return
				case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: record.Domain}:
					stats.Results++
				}
				if maxResults > 0 && stats.Results >= maxResults {
					session.DiscardHTTPResponse(resp)
					return
				}
			}

			// Close this page before the next request. A defer in the loop
			// would hold every body until the source returns.
			session.DiscardHTTPResponse(resp)

			pageInfo := windvaneResponse.Data.PageResponse
			var totalRecords, recordsPerPage int

			if totalRecords, err = strconv.Atoi(pageInfo.Total); err != nil {
				break
			}
			if recordsPerPage, err = strconv.Atoi(pageInfo.Count); err != nil {
				break
			}

			if page*recordsPerPage >= totalRecords {
				break
			}

			page++
		}

	}()

	return results
}

func (s *Source) Name() string {
	return "windvane"
}

func (s *Source) IsDefault() bool {
	return true
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

package windvane

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strconv"
	"sync"
	"testing"
	"time"

	"github.com/projectdiscovery/ratelimit"
	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// rewriteTransport sends every request to the test server's host while
// preserving the original path, so the source's hardcoded windvane URL
// still resolves to our handler.
type rewriteTransport struct {
	target *url.URL
}

func (r *rewriteTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	req.URL.Scheme = r.target.Scheme
	req.URL.Host = r.target.Host
	return http.DefaultTransport.RoundTrip(req)
}

// newPagedServer serves total subdomains split in pages of the requested
// count, with the page_response fields of the windvane API documentation,
// and records every requested page.
func newPagedServer(t *testing.T, total int) (*httptest.Server, func() []int) {
	t.Helper()
	var mu sync.Mutex
	var pages []int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			PageRequest struct {
				Page  int `json:"page"`
				Count int `json:"count"`
			} `json:"page_request"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		page, count := req.PageRequest.Page, req.PageRequest.Count
		mu.Lock()
		pages = append(pages, page)
		mu.Unlock()

		var resp response
		for i := (page - 1) * count; i < min(page*count, total); i++ {
			resp.Data.List = append(resp.Data.List, domainEntry{Domain: fmt.Sprintf("sub%d.example.com", i)})
		}
		resp.Data.PageResponse = pageInfo{
			Total:     strconv.Itoa(total),
			Count:     strconv.Itoa(count),
			TotalPage: strconv.Itoa((total + count - 1) / count),
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	}))
	t.Cleanup(server.Close)

	return server, func() []int {
		mu.Lock()
		defer mu.Unlock()
		return append([]int(nil), pages...)
	}
}

func runSource(t *testing.T, server *httptest.Server) (subs []string, errs []error) {
	t.Helper()
	return runSourceWithLimit(t, server, 0)
}

func runSourceWithLimit(t *testing.T, server *httptest.Server, maxResults int) (subs []string, errs []error) {
	t.Helper()
	target, err := url.Parse(server.URL)
	require.NoError(t, err)

	mrl, err := ratelimit.NewMultiLimiter(context.Background(), &ratelimit.Options{
		Key:         "windvane",
		IsUnlimited: false,
		MaxCount:    math.MaxInt32,
		Duration:    time.Millisecond,
	})
	require.NoError(t, err)
	session := &subscraping.Session{
		Client:           &http.Client{Transport: &rewriteTransport{target: target}, Timeout: 5 * time.Second},
		MultiRateLimiter: mrl,
		MaxResults:       maxResults,
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	ctxWithValue := context.WithValue(ctx, subscraping.CtxSourceArg, "windvane")

	source := &Source{}
	source.AddApiKeys([]string{"test-key"})
	for r := range source.Run(ctxWithValue, "example.com", session) {
		switch r.Type {
		case subscraping.Subdomain:
			subs = append(subs, r.Value)
		case subscraping.Error:
			errs = append(errs, r.Error)
		}
	}
	return subs, errs
}

// Pagination must stop after the last page instead of requesting one more
// empty page.
func TestWindvaneSource_StopsAfterLastPage(t *testing.T) {
	tests := []struct {
		name  string
		total int
		pages []int
	}{
		{name: "single page", total: 2, pages: []int{1}},
		{name: "full single page", total: 1000, pages: []int{1}},
		{name: "partial last page", total: 1500, pages: []int{1, 2}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			server, requestedPages := newPagedServer(t, tt.total)

			subs, errs := runSource(t, server)

			assert.Empty(t, errs)
			assert.Len(t, subs, tt.total)
			assert.Equal(t, tt.pages, requestedPages())
		})
	}
}

// With -max-results set, pagination must stop once the limit is reached
// instead of reading every page.
func TestWindvaneSource_HonorsMaxResults(t *testing.T) {
	tests := []struct {
		name       string
		maxResults int
		pages      []int
	}{
		{name: "limit ends a page", maxResults: 1000, pages: []int{1}},
		{name: "limit inside a page", maxResults: 1500, pages: []int{1, 2}},
		{name: "limit above the total", maxResults: 5000, pages: []int{1, 2, 3}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			server, requestedPages := newPagedServer(t, 3000)

			subs, errs := runSourceWithLimit(t, server, tt.maxResults)

			assert.Empty(t, errs)
			assert.Len(t, subs, min(tt.maxResults, 3000))
			assert.Equal(t, tt.pages, requestedPages())
		})
	}
}

package zoomeyeapi

import (
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"slices"
	"sync"
	"time"

	"github.com/projectdiscovery/subfinder/v2/pkg/subscraping"
)

// search results
type zoomeyeResults struct {
	Code  int `json:"code"`
	Total int `json:"total"`
	Data  []struct {
		Domain string `json:"domain"`
	} `json:"data"`
}

type apiKey struct {
	host string
	key  string
}

// Source is the passive scraping agent
type Source struct {
	mu      sync.Mutex
	stats   subscraping.Statistics
	apiKeys []string
}

// Run function returns all subdomains found with the service
func (s *Source) Run(ctx context.Context, domain string, session *subscraping.Session) <-chan subscraping.Result {
	results := make(chan subscraping.Result)
	s.mu.Lock()
	apiKeys := s.apiKeys
	s.mu.Unlock()

	go func() {
		var stats subscraping.Statistics
		defer func(startTime time.Time) {
			stats.TimeTaken = time.Since(startTime)
			s.mu.Lock()
			s.stats = stats
			s.mu.Unlock()
			close(results)
		}(time.Now())

		reportError := func(err error) {
			stats.Errors++
			select {
			case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Error, Error: err}:
			case <-ctx.Done():
			}
		}

		keys := subscraping.NewKeyRing(subscraping.CreateApiKeys(apiKeys, func(host, key string) apiKey {
			return apiKey{host: host, key: key}
		}))
		if keys.Empty() {
			stats.Skipped = true
			return
		}

		// Honor an optional per-source result limit (0 = no limit) so a single
		// domain can't drain an API quota by paginating to the end.
		maxResults := session.MaxResults

		const pageSize = 1000
		// Search web assets explicitly; the v2 API defaults to IPv4 assets.
		query := base64.StdEncoding.EncodeToString(fmt.Appendf(nil, "domain=%q", domain))
		for currentPage := 1; ; currentPage++ {
			select {
			case <-ctx.Done():
				return
			default:
			}
			body, err := json.Marshal(struct {
				Query    string `json:"qbase64"`
				Page     int    `json:"page"`
				PageSize int    `json:"pagesize"`
				Fields   string `json:"fields"`
				SubType  string `json:"sub_type"`
			}{
				Query: query, Page: currentPage, PageSize: pageSize,
				Fields: "domain", SubType: "web",
			})
			if err != nil {
				reportError(fmt.Errorf("encode ZoomEye search request: %w", err))
				return
			}
			resp, err := keys.Do(session, func(key apiKey) (*http.Response, error) {
				stats.Requests++
				headers := map[string]string{
					"API-KEY":      key.key,
					"Accept":       "application/json",
					"Content-Type": "application/json",
				}
				return session.Post(ctx, fmt.Sprintf("https://api.%s/v2/search", key.host), "", headers, bytes.NewReader(body))
			})
			if err != nil {
				if resp != nil {
					_ = resp.Body.Close()
				}
				reportError(err)
				return
			}

			var res zoomeyeResults
			err = json.NewDecoder(resp.Body).Decode(&res)
			_ = resp.Body.Close()

			if err != nil {
				reportError(fmt.Errorf("decode ZoomEye search response: %w", err))
				return
			}
			if res.Code != 60000 {
				reportError(fmt.Errorf("ZoomEye search failed with code %d", res.Code))
				return
			}
			for _, r := range res.Data {
				if r.Domain == "" {
					continue
				}
				select {
				case <-ctx.Done():
					return
				case results <- subscraping.Result{Source: s.Name(), Type: subscraping.Subdomain, Value: r.Domain}:
					stats.Results++
				}
				if maxResults > 0 && stats.Results >= maxResults {
					return
				}
			}
			if len(res.Data) == 0 || currentPage >= (res.Total-1)/pageSize+1 {
				return
			}
		}
	}()

	return results
}

// Name returns the name of the source
func (s *Source) Name() string {
	return "zoomeyeapi"
}

func (s *Source) IsDefault() bool {
	return false
}

func (s *Source) HasRecursiveSupport() bool {
	return false
}

func (s *Source) KeyRequirement() subscraping.KeyRequirement {
	return subscraping.RequiredKey
}

func (s *Source) NeedsKey() bool {
	return s.KeyRequirement() == subscraping.RequiredKey
}

func (s *Source) AddApiKeys(keys []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.apiKeys = slices.Clone(keys)
}

// Statistics returns a snapshot of the most recently completed run.
func (s *Source) Statistics() subscraping.Statistics {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stats
}

