func TestZoomeyeAPISource_StopsOnLastPage(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		req := decodeSearchRequest(t, r)
		assert.Equal(t, int(n), req.Page)
		w.Header().Set("Content-Type", "application/json")
		// pageSize is 1000, so total 1001 requires two pages.
		_, _ = fmt.Fprintf(w, `{"code":60000,"total":1001,"data":[{"domain":"p%d.example.com"}]}`, n)
	}))
	defer server.Close()

	source := &Source{}
	source.AddApiKeys([]string{"zoomeye.ai:test-key"})
	subs, errs := runSource(t, source, newTestSession(t, server), "example.com")

	assert.Empty(t, errs)
	assert.Equal(t, []string{"p1.example.com", "p2.example.com"}, subs)
	assert.Equal(t, 2, source.Statistics().Requests)
	assert.Equal(t, int32(2), atomic.LoadInt32(&hits))
}

// With -max-results set, pagination must stop once the limit is reached
// instead of reading every page.
func TestZoomeyeAPISource_HonorsMaxResults(t *testing.T) {
	var hits int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&hits, 1)
		w.Header().Set("Content-Type", "application/json")
		// pageSize is 1000, so total 3000 would take three pages of two names.
		_, _ = fmt.Fprintf(w, `{"code":60000,"total":3000,"data":[{"domain":"a%d.example.com"},{"domain":"b%d.example.com"}]}`, n, n)
	}))
	defer server.Close()

	source := &Source{}
	source.AddApiKeys([]string{"zoomeye.ai:test-key"})
	subs, errs := runSource(t, source, newTestSessionWithLimit(t, server, 3), "example.com")

	assert.Empty(t, errs)
	assert.Equal(t, []string{"a1.example.com", "b1.example.com", "a2.example.com"}, subs)
	assert.Equal(t, 2, source.Statistics().Requests)
	assert.Equal(t, int32(2), atomic.LoadInt32(&hits))
}

package subscraping

import (
	"context"
	"net/http"
	"time"

	"github.com/projectdiscovery/ratelimit"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

type CtxArg string

const (
	CtxSourceArg CtxArg = "source"
)

type CustomRateLimit struct {
	Custom         mapsutil.SyncLockMap[string, uint]
	CustomDuration mapsutil.SyncLockMap[string, time.Duration]
}

// BasicAuth request's Authorization header
type BasicAuth struct {
	Username string
	Password string
}

// Statistics contains statistics about the scraping process
type Statistics struct {
	TimeTaken time.Duration
	Requests  int
	Errors    int
	Results   int
	Skipped   bool
}

// KeyRequirement represents the API key requirement level for a source
type KeyRequirement int

const (
	NoKey KeyRequirement = iota
	OptionalKey
	RequiredKey
)

// Source is an interface inherited by each passive source
type Source interface {
	// Run takes a domain as argument and a session object
	// which contains the extractor for subdomains, http client
	// and other stuff.
	Run(context.Context, string, *Session) <-chan Result

	// Name returns the name of the source. It is preferred to use lower case names.
	Name() string

	// IsDefault returns true if the current source should be
	// used as part of the default execution.
	IsDefault() bool

	// HasRecursiveSupport returns true if the current source
	// accepts subdomains (e.g. subdomain.domain.tld),
	// not just root domains.
	HasRecursiveSupport() bool

	// KeyRequirement returns the API key requirement level for this source
	KeyRequirement() KeyRequirement

	// NeedsKey returns true if the source requires an API key.
	// Deprecated: Use KeyRequirement() instead for more granular control.
	NeedsKey() bool

	AddApiKeys([]string)

	// Statistics returns the scrapping statistics for the source
	Statistics() Statistics
}

// SubdomainExtractor is an interface that defines the contract for subdomain extraction.
type SubdomainExtractor interface {
	Extract(text string) []string
}

// RequestLimiter waits for permission to send a source request.
type RequestLimiter interface {
	Wait(context.Context, string) error
}

// Session is the option passed to the source, an option is created
// uniquely for each source.
type Session struct {
	//SubdomainExtractor
	Extractor SubdomainExtractor
	// Client is the current http client
	Client *http.Client
	// Rate limit instance
	MultiRateLimiter *ratelimit.MultiLimiter
	// RequestLimiter, when set, replaces MultiRateLimiter for HTTP requests.
	// Its lifetime belongs to the caller and may span multiple sessions.
	RequestLimiter RequestLimiter
	// Timeout is the timeout in seconds for requests
	Timeout int
	// MaxResults is the maximum number of results a source should emit
	// before stopping. A value of 0 means no limit (default behavior).
	// Sources that paginate can honor this to avoid unnecessary requests
	// (e.g. to stay within API quotas).
	MaxResults int
	// MaxResponseBodySize is the maximum number of bytes read from a
	// passive-source HTTP response body. A value of 0 means no limit
	// (default behavior). When set, bodies are truncated via LimitReader
	// so a malicious or oversized upstream cannot OOM the process.
	MaxResponseBodySize int64
}

// Result is a result structure returned by a source
type Result struct {
	Type   ResultType
	Source string
	Value  string
	Error  error
}

// ResultType is the type of result returned by the source
type ResultType int

// Types of results returned by the source
const (
	Subdomain ResultType = iota
	Error
)

package subscraping

import (
	"math/rand"
	"strings"

	"github.com/projectdiscovery/gologger"
)

const MultipleKeyPartsLength = 2

// Deprecated: Use NewKeyRing, which also moves past rejected keys.
func PickRandom[T any](v []T, sourceName string) T {
	var result T
	length := len(v)
	if length == 0 {
		gologger.Debug().Msgf("Cannot use the %s source because there was no API key/secret defined for it.", sourceName)
		return result
	}
	return v[rand.Intn(length)]
}

func CreateApiKeys[T any](keys []string, provider func(k, v string) T) []T {
	var result []T
	for _, key := range keys {
		if keyPartA, keyPartB, ok := createMultiPartKey(key); ok {
			result = append(result, provider(keyPartA, keyPartB))
		}
	}
	return result
}

func createMultiPartKey(key string) (keyPartA, keyPartB string, ok bool) {
	parts := strings.Split(key, ":")
	ok = len(parts) == MultipleKeyPartsLength

	if ok {
		keyPartA = parts[0]
		keyPartB = parts[1]
	}

	return
}

package testutils

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func RunSubfinderAndGetResults(debug bool, domain string, extra ...string) ([]string, error) {
	cmd := exec.Command("bash", "-c")
	cmdLine := fmt.Sprintf("echo %s | %s", domain, "./subfinder ")
	cmdLine += strings.Join(extra, " ")
	cmd.Args = append(cmd.Args, cmdLine)
	if debug {
		cmd.Args = append(cmd.Args, "-v")
		cmd.Stderr = os.Stderr
		fmt.Println(cmd.String())
	} else {
		cmd.Args = append(cmd.Args, "-silent")
	}
	data, err := cmd.Output()
	if debug {
		fmt.Println(string(data))
	}
	if err != nil {
		return nil, err
	}
	var parts []string
	items := strings.SplitSeq(string(data), "\n")
	for i := range items {
		if i != "" {
			parts = append(parts, i)
		}
	}
	return parts, nil
}

// TestCase is a single integration test case
type TestCase interface {
	Execute() error
}
